/* Lance content studio. All generation is explicit and all media stays durable. */
'use strict';
const C=StudioCore;
const R=StudioReverse;
const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key=scope=>'lance_studio_v2_'+scope;
let scope=localStorage.getItem('lance_studio_scope')||'xinxuan';
let route={view:'home',id:null,tab:'quick'},db,settings,job=null,stop=false,health=null,search='';
let exportURL=null;
try{settings=JSON.parse(localStorage.getItem('lance_studio_settings')||'{}');}catch{settings={};}
settings={server:settings.server||''}; // Model routes and credentials are server-only.
localStorage.setItem('lance_studio_settings',JSON.stringify(settings));
function read(scopeName){
  const stored=localStorage.getItem(key(scopeName));
  if(stored){try{const parsed=JSON.parse(stored);if(!Array.isArray(parsed.topics)||!Array.isArray(parsed.projects)||!Array.isArray(parsed.assets))throw Error();return upgradeReverse(parsed,scopeName);}catch{throw Error('工作台数据无法读取，已保留原数据，请通过备份恢复。');}}
  const data={version:2,topics:[],projects:[],assets:[],exports:[],preferences:'',imported:false};
  try{
    const old=JSON.parse(localStorage.getItem('xuan_ti_ku_data_'+scopeName)||'[]');
    data.topics=old.map(C.importLegacy);
    const plans=JSON.parse(localStorage.getItem('project_plans_'+scopeName)||'[]');
    data.projects=plans.map(p=>({...C.project(p.title),id:'legacy-'+p.id,idea:p.description||p.shootTheme||'',date:p.liveDate||'',topicIds:(p.topicIds||[]).map(id=>'legacy-'+id).filter(id=>data.topics.some(t=>t.id===id))}));
    for(const p of data.projects)for(const id of p.topicIds)data.topics.find(t=>t.id===id).projectId=p.id;
    for(const oldTopic of old){const t=data.topics.find(t=>t.legacyId===oldTopic.id);if(t&&!t.projectId&&oldTopic.session){let p=data.projects.find(p=>p.title===oldTopic.session);if(!p){p=C.project(oldTopic.session);p.date=oldTopic.sessionDate||'';data.projects.push(p);}p.topicIds.push(t.id);t.projectId=p.id;}}
    data.imported=old.length>0;
  }catch(error){console.warn('Legacy data remains untouched',error.message);}
  return upgradeReverse(data,scopeName);
}
function save(){
  try{const prior=localStorage.getItem(key(scope));if(prior)localStorage.setItem(key(scope)+'_previous',prior);localStorage.setItem(key(scope),JSON.stringify(db));$('.save-state')?.replaceChildren(document.createTextNode('已保存到本机 · '+new Date().toLocaleTimeString('zh-CN')));}
  catch{throw Error('本地存储空间不足，内容仍在当前页面，请立即导出备份。');}
}
function notify(message,tone='info'){const n=$('#notification');n.textContent=message;n.dataset.tone=tone;n.setAttribute('role',tone==='error'?'alert':'status');n.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.style.display='none',6500);}
function showError(error){const message=error?.message||String(error),d=$('#dialog'),box=$('#dialog-error');if(d?.open&&box){box.textContent=message;box.hidden=false;const invalid=d.querySelector('input:invalid,textarea:invalid,select:invalid')||d.querySelector('input:not([type="hidden"]),textarea,select');if(invalid){invalid.setAttribute('aria-invalid','true');invalid.focus();}}else notify(message,'error');}
const btn=(label,action,extra='',primary=false)=>{const cls=extra.match(/class="([^"]*)"/)?.[1]||'';return `<button class="${primary?'primary ':''}${cls}" data-action="${action}" ${extra.replace(/class="[^"]*"/,'')}>${label}</button>`;};
const upload=(label,action,extra='',accept='image/*')=>`<label class="upload">${label}<input type="file" data-upload="${action}" ${extra} accept="${accept}"></label>`;
const field=(label,path,value,wide=false,short=false)=>`<label class="${wide?'wide':''}">${label}<textarea data-field="${esc(path)}" class="${short?'short':''}">${esc(value)}</textarea></label>`;
const mediaURL=a=>(settings.server||'').replace(/\/$/,'')+'/media/'+encodeURIComponent(a.localId);
const currentTopic=()=>db.topics.find(t=>t.id===route.id);
const currentProject=()=>db.projects.find(p=>p.id===route.id);
const ts=t=>db.topics.indexOf(t);
const ps=p=>db.projects.indexOf(p);
function get(path){return path.split('.').reduce((v,k)=>v?.[k],db);}
function set(path,value){const bits=path.split('.');const leaf=bits.pop();const parent=bits.reduce((v,k)=>v[k],db);parent[leaf]=value;}
function context(t){const p=db.projects.find(p=>p.id===t.projectId);const refs=resolvedReferences(t).assets;return {form:t.form,motif:t.motif,inspirationSource:t.inspirationSource,exploration:t.exploration,creator:profileContext(),referenceFolders:referenceContext(t).folders,aesthetic:referenceContext(t).aesthetic,project:p?{title:p.title,kind:p.kind,personalRole:p.personalRole,deliverables:p.deliverables,fields:p.fields,idea:p.idea}:null,title:t.title,idea:t.idea,quick:t.quick.fields,cover:C.ensureCover(t),approved:t.quick.approved||t.directionApproved,preferences:db.preferences,assets:refs.map(a=>({name:a.name,kind:a.kind,dimensions:a.dimensions,dimensionsConfirmed:a.dimensionsConfirmed,requirements:a.requirements,inventory:a.inventory,analysis:a.analysis,selectedOutfits:a.outfits?.filter(o=>o.selected)})),format:'4:3 Open Gate，构图兼顾中央9:16主输出和16:9保底。尺寸不明处必须列为待确认。'};}
function referenceIDs(t){return folderImageIDs(t);}
function renderBudgetMini(){
  const p=C.budgetPlan(db.budgetPlan),estimate=C.monthlyCostRange(p),remaining=p.monthlyCny-estimate.cost[1];
  return `<details class="budget-mini"><summary><span>本月AI预算</span><strong>¥${estimate.cost[0].toFixed(0)}–¥${estimate.cost[1].toFixed(0)}</strong></summary><div class="budget-mini-body"><small class="${remaining<0?'budget-over':''}">${remaining>=0?`上限估算约余 ¥${remaining.toFixed(0)}`:`上限估算约超 ¥${Math.abs(remaining).toFixed(0)}`}</small><label>预算（元）<input type="number" min="1" data-number data-budget data-field="budgetPlan.monthlyCny" value="${p.monthlyCny}"></label><div class="budget-mini-grid"><label>项目<input type="number" min="1" data-number data-budget data-field="budgetPlan.projects" value="${p.projects}"></label><label>脚本<input type="number" min="1" data-number data-budget data-field="budgetPlan.scripts" value="${p.scripts}"></label><label>深化<input type="number" min="1" data-number data-budget data-field="budgetPlan.deepScripts" value="${p.deepScripts}"></label></div><small>参考量，不限制实际数量；生成前仍会显示本次估算。</small></div></details>`;
}
function render(){
  const nav=[['home','工作台'],['fragments','灵感速记'],['inbox','随身收件箱'],['topics',scope==='personal'?'选题库':'脚本与汇报'],['projects',scope==='personal'?'我的项目':'专场排期'],['reverse','视频反推创意'],['radar','案例雷达'],['aesthetic','审美参考'],['profile','我的资料'],['archive','成果与备份']];
  const navGroups=[['首页',nav.slice(0,1)],['记录',nav.slice(1,3)],['创作',nav.slice(3,6)],['资料',nav.slice(6)]];
  $('#app').innerHTML=`<div class="shell"><aside class="side"><div class="brand">LANCE<small>CONTENT STUDIO / 内容工作台</small></div><select id="scope" aria-label="身份空间"><option value="xinxuan" ${scope==='xinxuan'?'selected':''}>My·工作</option><option value="personal" ${scope==='personal'?'selected':''}>My·个人</option></select><nav>${navGroups.map(([group,items])=>`<div class="nav-group"><small>${group}</small>${items.map(([id,label])=>btn(label,'nav',`data-view="${id}" class="${route.view===id?'active':''} ${id==='fragments'?'capture-nav':''}"`)).join('')}</div>`).join('')}</nav>${scope==='xinxuan'?renderBudgetMini():''}<footer>个人创意资产<br>本机保存 · 可导出完整备份<br><a href="mobile.html" target="_blank" rel="noopener">打开手机随身版 ↗</a><br><a href="legacy.html" target="_blank" rel="noopener">打开旧版存档 ↗</a></footer></aside><main class="main"><div class="topbar"><span>${scope==='xinxuan'?'My·工作 / 内容策划':'My·个人 / 创作'} / ${nav.find(n=>n[0]===route.view)?.[1]||(route.view==='supply'?'创意补给':'项目工程')}</span><div class="actions"><span class="save-state">本机自动保存</span>${btn(health?.ok?'本机服务已连接':'连接设置','settings')}</div></div>${job?`<div class="job" role="status"><strong>${esc(job.title)}</strong><progress value="${job.done}" max="${job.total}"></progress><div class="actions"><span>${job.done}/${job.total} · ${esc(job.detail||'')}</span>${btn(stop?'正在停止…':'停止后续生成','stop')}</div></div>`:''}${route.view==='home'?fragmentCaptureBanner():''}<div id="view">${renderView()}</div></main>${!['fragments','topic','reverse-detail'].includes(route.view)?btn('<span aria-hidden="true">＋</span> 记灵感','nav','data-view="fragments" class="capture-fab" title="随手记录语音或文字灵感"',true):''}</div>`;
  renderReportTools();
}
function renderReportTools(){
  const kind=route.view==='project'?'project':'topic';
  const item=kind==='project'?currentProject():currentTopic();
  if(!item||route.view!=='project'||scope==='personal'&&route.tab==='idea'||isPersonalProject(item))return;
  const report=StudioPpt.ensureReport(item),path=(kind==='project'?'projects.'+ps(item):'topics.'+ts(item))+'.report';
  const modes=kind==='project'?['decision','full']:['decision','full','execution'];
  const direction=(kind==='project'?item.stage:item.quick.stage)!=='full';
  const html=`<section class="panel report-tools"><h2>工作阶段 · ${direction?'方向汇报':'完整交付'}</h2><div class="actions">${btn('① 方向汇报（3小时响应）','workflow-stage',`data-id="${item.id}" data-stage="direction"`,direction)}${btn('② 完整交付（补齐素材）','workflow-stage',`data-id="${item.id}" data-stage="full"`,!direction)}</div><p class="muted">方向阶段只生成文字；可直接导出老板决策版。完整交付才检查全部图片、封面与视频。</p><h2>PPT汇报</h2><p class="muted">老板决策版用于方向会；完整策划版包含全部强制素材；单条执行版包含确认稿、25镜与AI成片。</p><div class="actions">${modes.map(mode=>btn(StudioPpt.MODES[mode],'report-options',`data-id="${item.id}" data-kind="${kind}" data-mode="${mode}"`,mode==='decision')).join('')}</div><details><summary>编辑汇报要点（主推方向、已知事实、待拍板事项）</summary><p class="muted">不填时引用已有大纲和寓意。正文过长时，主汇报展示摘要，全文保存在备注及完整策划附件。</p><div class="actions">${btn('AI提炼汇报要点','report-refine',`data-id="${item.id}" data-kind="${kind}"`)}</div><div class="formgrid">${StudioPpt.REPORT_FIELDS.map(([k,label])=>field(label,path+'.'+k,report[k])).join('')}${kind==='topic'?field('本条在专场中的任务（写入专场分工表）',path+'.role',report.role||'',true):''}</div></details></section>`;
  $('#view > .hero')?.insertAdjacentHTML('afterend',html);
  const download=$('#view > .hero [data-action="export-topic"],#view > .hero [data-action="export-project"]');
  if(download)download.textContent='选择PPT版本';
}
function showReportOptions(item,kind,mode){
  const status=StudioPpt.reportStatus(item,kind,db.topics,mode),plan=StudioPpt.planDeck(item,kind,db.topics,mode);
  const modes=kind==='project'?['decision','full']:['decision','full','execution'];
  const missing=status.deliveryMissing||status.missing;
  const note=mode==='decision'?'前面给出推荐方向、依据与待确认事项。只用于方向讨论，完整快速交付仍需全部素材。':mode==='execution'?'包含已确认的快速汇报、执行方案、25张AI分镜图和完整AI成片。':'先展示主汇报，再附完整脚本、A/B/C封面、3–5张视觉参考和每条三段8秒AI视频。';
  dialog('导出'+plan.label,`<div class="actions">${modes.map(m=>btn(StudioPpt.MODES[m],'report-options',`data-id="${item.id}" data-kind="${kind}" data-mode="${m}"`,m===mode)).join('')}</div><p class="muted" style="margin-top:18px">${note}</p><p>${plan.slides.length}页，主汇报${plan.overviewCount}页${plan.draft?' · 方向讨论稿，素材待补齐':''}</p>${missing.length?`<details class="report-missing" ${!status.ready?'open':''}><summary>${status.ready?'完整交付待办':'当前版本待补充'}（${missing.length}项）</summary><ul>${missing.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details>`:''}<details open><summary>页序预览</summary><ol class="report-outline">${plan.slides.map((s,i)=>`<li>${i===plan.overviewCount?'<strong>附件开始</strong> · ':''}${esc(s.title)}</li>`).join('')}</ol></details><p class="muted">文件会保存到浏览器下载目录，同时存入“成果与备份”。视频内嵌于完整策划版与单条执行版，请在汇报设备上试播。</p>`,btn('下载'+plan.label,'report-download',`data-id="${item.id}" data-kind="${kind}" data-mode="${mode}" ${status.ready?'':'disabled'}`,true));
}
function hero(kicker,title,subtitle,actions=''){return `<div class="hero"><div><div class="eyebrow">${kicker}</div><h1>${esc(title)}</h1><p class="muted">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function empty(title,body,action=''){return `<div class="empty"><h2>${title}</h2><p>${body}</p>${action}</div>`;}
function topicCard(t){if(scope==='personal')return personalTopicCard(t);const s=C.quickStatus(t),d=C.deepStatus(t),direction=C.directionStatus(t);return `<article class="card"><span class="badge ${s.ready?'':'bad'}">${s.ready?'完整交付齐备':direction.ready?'方向可讨论 · 完整素材待补':'方向待完善'}</span><h3>${esc(t.title)}</h3><p>${esc((t.idea||t.quick.fields.outline||'从一句想法开始').slice(0,150))}</p><div class="progress"><div style="width:${s.percent}%"></div></div><p>${s.covers}/3套封面　${s.images}/${t.quick.images.length}张图　${s.videos}/3段8秒视频</p><div class="actions">${btn('快速汇报','topic',`data-id="${t.id}"`,true)}${btn(`深入优化 · ${d.images}/25图`,'deep',`data-id="${t.id}"`)}</div></article>`;}
function projectCard(p){if(isPersonalProject(p))return personalProjectCard(p);const s=C.sessionStatus(p,db.topics),direction=C.directionStatus(p,'project',db.topics);return `<article class="card"><span class="badge ${s.ready?'':'bad'}">${s.ready?'完整交付齐备':direction.ready?'方向可讨论 · 完整素材待补':'方向待完善'}</span><h3>${esc(p.title)}</h3><p>${esc(p.date||'日期待定')} · ${s.items.length}/${C.sessionTarget(p)}条故事脚本</p><p>${s.covers}/${C.sessionTarget(p)*3}套封面　${s.images}张视觉参考　${s.videos}/${C.sessionTarget(p)*3}段8秒视频</p>${btn('进入专场','project',`data-id="${p.id}"`,true)}</article>`;}
function renderView(){
  if(route.view==='fragments')return renderFragments();
  if(route.view==='inbox')return renderMobileInbox();
  if(route.view==='home'&&scope==='personal')return renderPersonalHome();
  if(route.view==='home')return hero('YOUR CREATIVE WORKSPACE','让一个想法，成为一场作品。','快速汇报与深入优化，共用同一份创意和项目资料。',btn('新建单条脚本','new-topic','',true)+btn(scope==='personal'?'新建个人项目':'新建专场','new-project')+(scope==='personal'?'':btn('AI创意补给','nav','data-view="supply"')))+`<div class="metrics"><div class="card"><div class="metric">${db.topics.length}</div><small>故事脚本</small></div><div class="card"><div class="metric">${db.topics.filter(t=>C.quickStatus(t).ready).length}</div><small>完整交付齐备</small></div><div class="card"><div class="metric">${db.projects.length}</div><small>专场项目</small></div></div><div class="rule">方向汇报：整体主张、各条故事分工和待拍板事项，不强制生成图片或视频。<br>完整交付：按计划片数，每条保留完整脚本、A/B/C封面、3–5张参考图和三段8秒AI视频。</div><div class="section-head"><h2>继续创作</h2>${btn('查看所有脚本','nav','data-view="topics"')}</div><div class="grid">${db.topics.slice(0,4).map(topicCard).join('')||empty('还没有脚本','输入想法，或从旧版数据、备份开始。',btn('建立第一条脚本','new-topic','',true))}</div>`;
  if(route.view==='topics')return hero('STORIES',scope==='personal'?'个人选题库':'脚本与汇报',scope==='personal'?'自由记录，慢慢探索；确定要推进时，再进入脚本与制作。':'每条脚本拥有独立的参考素材、反馈和修改记录。',btn(scope==='personal'?'新建选题／灵感':'新建脚本','new-topic','',true))+`<input class="workbench-search" id="search" placeholder="搜索标题或想法" value="${esc(search)}"><div class="grid" style="margin-top:20px">${db.topics.filter(t=>(t.title+t.idea).includes(search)).map(topicCard).join('')}</div>`;
  if(route.view==='projects'&&scope==='personal')return hero('MY PROJECTS','我的个人项目','导演、摄影师、个人博主：按实际项目管理，不套用工作专场规则。',btn('新建个人项目','new-project','',true))+`<div class="grid">${db.projects.map(projectCard).join('')||empty('建立个人项目','商业拍摄、纪录片、短片、博主内容或其他项目。')}</div>`;
  if(route.view==='projects')return hero('SESSION PLANNING','专场排期','按实际需求设置片数；先确认方向，再补齐完整交付。',btn('新建专场','new-project','',true))+`<div class="grid">${db.projects.map(projectCard).join('')||empty('创建一个专场','先确定创意方向和排期，再规划所需数量的故事。')}</div>`;
  if(route.view==='topic')return renderTopic(currentTopic());
  if(route.view==='project')return renderProject(currentProject());
  if(route.view==='radar')return renderRadar();
  if(route.view==='aesthetic')return renderAesthetic();
  if(route.view==='profile')return renderProfile();
  if(route.view==='supply'&&scope!=='personal')return renderInspiration();
  if(['scenes','wardrobe'].includes(route.view))return renderLibrary();
  if(route.view==='asset')return renderAsset(db.assets.find(a=>a.id===route.id));
  if(route.view==='reverse')return renderReverse();
  if(route.view==='reverse-detail')return renderReverseDetail(db.reverse.find(r=>r.id===route.id));
  if(route.view==='archive')return renderArchive();
  return '';
}
function readiness(s){return `<div class="rule"><strong>${s.stage==='direction'?(s.ready?'方向汇报可讨论（不代表完整交付）':'方向信息待完善'):(s.ready?'交付内容已齐备':'尚未达到交付标准')}</strong>${s.missing.length?`<p class="missing" style="margin:8px 0 0">待补充：${esc(s.missing.join('、'))}</p>`:''}</div>`;}
function upgradeReverse(data,scopeName){
  upgradeProfile(data,scopeName);
  data.budgetPlan=C.budgetPlan(data.budgetPlan);
  for(const t of data.topics||[])C.ensureCover(t);
  for(const p of data.projects||[]){p.targetCount=C.sessionTarget(p);if(!p.stage)p.stage='direction';}
  if(!Array.isArray(data.reverse))data.reverse=[];
  data.reverse=data.reverse.filter(r=>!r?.legacyId&&!r?.legacy);
  for(const r of data.reverse){
    if(!r.purpose)r.purpose='reference';
    if(!Array.isArray(r.supportingFiles))r.supportingFiles=[];
    if(!Array.isArray(r.transcriptions))r.transcriptions=[];
    if(typeof r.sourceLink!=='string')r.sourceLink='';
    if(!('sourceInfo'in r))r.sourceInfo=null;
    delete r.history;
    delete r.legacyId;
    delete r.legacy;
    if(r.analysis)delete r.analysis.legacyStoryboard;
  }
  delete data.reverseMigrationError;
  localStorage.removeItem('xuan_ti_ku_reverse_'+scopeName);
  return data;
}
function reverseTranscriptionHTML(r){
  const rows=(r.transcriptions||[]).slice().reverse();
  if(!rows.length)return '<p class="muted">还没有AI转写候选。转写不会自动改写你核对过的文字。</p>';
  return `<div class="list">${rows.map(x=>`<div class="card"><p class="preview-copy">${esc(x.text)}</p><small>${esc(x.modelVersion||'语音模型')} · ${esc((x.createdAt||'').slice(0,16))}${x.acceptedAt?' · 已采用':''}</small><div class="actions">${btn(x.acceptedAt?'已采用这份转写':'采用这份转写','reverse-accept-transcript',`data-id="${r.id}" data-transcription="${x.id}" ${x.acceptedAt?'disabled':''}`,!x.acceptedAt)}</div></div>`).join('')}</div>`;
}
function reverseSupportHTML(r,path){const info=r.sourceInfo,files=r.supportingFiles||[];return `<div class="panel"><div class="section-head"><h2>来源链接与手动补全资料</h2>${upload('上传补充资料','reverse-support',`data-id="${r.id}" multiple`,'.txt,.md,.docx,.pdf,image/png,image/jpeg,image/webp,video/mp4,video/quicktime,video/webm,audio/mpeg,audio/wav,audio/mp4')}</div><label>公开视频或作品页链接<div class="inline-input"><input data-field="${path}.sourceLink" value="${esc(r.sourceLink||'')}" placeholder="粘贴 https:// 链接或带链接的分享文字">${btn('解析链接','reverse-link',`data-id="${r.id}"`,true)}</div></label><p class="muted">只解析无需登录的公开页面、视频直链及页面公开暴露的视频。不绕过登录、版权保护或平台限制。</p>${info?`<div class="callout"><strong>${esc(info.title||info.siteName||'已解析来源')}</strong><p>${esc(info.description||'')}</p><p>${esc(info.notice||'')}</p>${info.finalUrl?`<a href="${esc(info.finalUrl)}" target="_blank" rel="noopener noreferrer">打开原链接 ↗</a>`:''}</div>`:''}<p class="muted">可追加当时脚本、策划案、聊天纪要、海报、现场照、参考图或其他成片。TXT／MD／DOCX／PDF会尝试提取文字，扫描件会尝试OCR；图片可进入看图分析。</p><div class="list">${files.map((f,i)=>`<div class="card"><h3>${esc(f.name||'补充资料')}</h3><p>${esc(f.kind)}${f.extractedText?` · 已提取 ${f.extractedText.length} 字`:''}</p>${f.kind==='image'||f.kind==='video'?mediaMarkup(f):`<a href="${mediaURL(f)}" target="_blank" rel="noopener">打开原文件 ↗</a>`}${f.extractionNotice?`<p class="muted">${esc(f.extractionNotice)}</p>`:''}${f.error?`<p class="missing">${esc(f.error)}</p>`:''}${field('这份资料说明了什么',`${path}.supportingFiles.${i}.note`,f.note||'',true)}${f.extractedText?`<details><summary>查看／修正提取文字</summary>${field('提取文字',`${path}.supportingFiles.${i}.extractedText`,f.extractedText,true)}</details>`:''}${f.kind==='image'||f.extractedText?`<label><input type="checkbox" data-bool data-field="${path}.supportingFiles.${i}.includeInAnalysis" ${f.includeInAnalysis?'checked':''}> 允许这份资料进入下次AI反推</label>`:'<p class="muted">这种附件目前只归档；请在说明中填写你已核对的信息。</p>'}<div class="actions">${btn('移出此反推','reverse-support-remove',`data-id="${r.id}" data-index="${i}"`)}</div></div>`).join('')||'<p class="muted">还没有补充资料。</p>'}</div></div>`;}
async function reverseFrames(r){if(!r.video)throw Error('请先上传原视频');const {jobId}=await api('frames',{localId:r.video.localId});const frames=await pollJob(jobId);if(!Array.isArray(frames)||frames.length!==12||frames.some(f=>!C.assetOK(f,'image')))throw Error('关键帧提取不完整，旧数据已保留');r.frames=frames;save();}
async function reverseSupportFiles(e){if(job)throw Error('请等待当前任务结束');const r=db.reverse.find(r=>r.id===e.dataset.id),files=[...e.files];if(!r||!files.length)return;const errors=[];await withJob('保存反推补充资料',files.length,async()=>{for(const file of files){if(stop)break;try{const item=await api('upload',file);item.name=file.name;item.note='';item.includeInAnalysis=item.kind==='image';if(['.txt','.md','.docx','.pdf'].some(ext=>file.name.toLowerCase().endsWith(ext))){try{const extracted=await api('document/text',{localId:item.localId});item.extractedText=extracted.text;item.extractionNotice=extracted.notice;item.includeInAnalysis=true;}catch(error){item.error=error.message;}}r.supportingFiles.push(item);save();}catch(error){errors.push(file.name+'：'+error.message);}progress(file.name);}if(errors.length)throw Error('部分资料保存失败：'+errors.join('；'));});}
async function reverseAction(action,e){
  const r=db.reverse.find(r=>r.id===e.dataset.id);
  if(action==='reverse-new'){dialog('建立视频反推',`<label>反推用途<select id="reverse-purpose"><option value="reference">喜欢的参考片：拆创作意图、概念和脚本</option><option value="archive">已完成的历史项目：重建遗失方案与成果</option></select></label><label>视频标题<input id="reverse-title" required></label><label>类型<input id="reverse-type" value="预热视频"></label>`,btn('创建反推案例','reverse-create','',true));return;}
  if(action==='reverse-create'){const title=$('#reverse-title').value.trim();if(!title)throw Error('请填写视频标题');const record=R.create(title,$('#reverse-purpose').value);record.type=$('#reverse-type').value.trim()||'未分类';db.reverse.push(record);route={view:'reverse-detail',id:record.id};save();close();render();return;}
  if(!r)throw Error('找不到反推记录');
  if(action==='reverse-open'){route={view:'reverse-detail',id:r.id};render();return;}
  if(action==='reverse-link'){const value=document.querySelector(`[data-field="reverse.${db.reverse.indexOf(r)}.sourceLink"]`)?.value||r.sourceLink;r.sourceLink=A.link(value);await withJob('解析公开链接',1,async()=>{const result=await api('link/import',{url:r.sourceLink}),asset=result.asset;delete result.asset;r.sourceInfo={...result,parsedAt:new Date().toISOString()};if(asset){asset.name=result.title||'链接视频';if(!r.video){r.video=asset;r.frames=[];r.analysis=null;}else{asset.note='链接解析得到的补充视频；当前原片未被覆盖';asset.includeInAnalysis=false;r.supportingFiles.push(asset);}}save();progress(result.notice||'链接已解析');});return;}
  if(action==='reverse-support-remove'){const index=Number(e.dataset.index);if(!Number.isInteger(index)||!r.supportingFiles[index])throw Error('补充资料不存在');r.supportingFiles.splice(index,1);save();render();notify('已从本条反推移出；没有删除本机原媒体。');return;}
  if(action==='reverse-transcribe'){
    if(!r.video?.hasAudio)throw Error('这个原片没有可识别音轨');
    if(!confirm('转写会调用豆包语音服务，可能产生少量按量费用。结果先作为候选，不会自动覆盖你核对过的台词。确定开始？'))return;
    await withJob('转写原片音轨',1,async()=>{await ensureService();if(!health.speechConfigured)throw Error('豆包语音服务端凭据未配置');const {jobId}=await api('transcribe',{localId:r.video.localId});const result=await pollJob(jobId);r.transcriptions.push({...result,id:C.uid(),createdAt:new Date().toISOString(),acceptedAt:null});save();progress('转写候选已保存，请人工核对');});return;
  }
  if(action==='reverse-accept-transcript'){
    const candidate=(r.transcriptions||[]).find(x=>x.id===e.dataset.transcription);if(!candidate)throw Error('转写候选不存在');if(candidate.acceptedAt)return;
    const text=String(candidate.text||'').trim();if(!text)throw Error('这份转写没有有效文字');
    r.transcript=[r.transcript.trim(),text].filter(Boolean).join('\n\n');candidate.acceptedAt=new Date().toISOString();save();render();notify('已加入“你核对过的台词／声音说明”，请在下次AI反推前手动校正。');return;
  }
  if(action==='reverse-frames'||action==='reverse-analyze'){await withJob(action==='reverse-frames'?'提取视频证据':'视频反推创意',2,async()=>{try{await ensureService();if(action==='reverse-frames'||!r.frames.length)await reverseFrames(r);progress('关键帧已保存');if(action==='reverse-analyze'&&!stop){const plan=R.referencePlan(r);R.accept(r,await chat(R.prompt(r),plan.ids),plan.manifest.filter(x=>x.kind==='videoFrame').map(x=>x.frameIndex));save();progress('反推结果已保存，待你核对');}}catch(error){r.error=error.message;save();throw error;}});return;}
  if(action==='reverse-topic'){const p=db.projects.find(p=>p.id===r.projectId);if(p&&p.topicIds.length>=C.sessionTarget(p)&&!isPersonalProject(p))throw Error('已达到计划片数，请先增加专场计划片数或调整关联');const t=R.toTopic(r);db.topics.push(t);if(p)p.topicIds.push(t.id);r.topicIds.push(t.id);save();route={view:'topic',id:t.id,tab:'quick'};render();notify('已创建可编辑的新选题；快速汇报仍需补齐A/B/C三套封面、3–5图和三个8秒AI视频。');return;}
  if(action==='reverse-reference'){if(!r.analysis)throw Error('请先完成反推分析');const all=globalAssets(),f=r.analysis.fields;let item=all.find(a=>a.sourceReverseId===r.id);if(!item){item=A.entry(r.title+' · 反推档案');item.category=r.purpose==='archive'?'历史项目重建':'视频参考拆解';item.folderIds=[];item.sourceReverseId=r.id;all.push(item);}item.notes=[f.intent,f.concept,f.outline,f.reuse].filter(Boolean).join('\n');item.requirements=item.notes;item.link=r.sourceLink||'';item.files=[...(r.video?[C.clone(r.video)]:[]),...C.clone(r.frames),...C.clone(r.supportingFiles||[])];item.reversePurpose=r.purpose;item.sourceInfo=C.clone(r.sourceInfo);item.reverseAnalysis=C.clone(r.analysis);item.updatedAt=new Date().toISOString();saveAesthetic(all);notify('完整反推档案已保存到当前空间审美参考库，可继续加入项目文件夹。');return;}
  if(action==='reverse-scene'||action==='reverse-wardrobe'){if(!r.analysis)throw Error('请先反推分析');const kind=action==='reverse-scene'?'scene':'wardrobe',f=r.analysis.fields;const a={id:C.uid(),name:r.title+(kind==='scene'?' · 场景':' · 服装'),kind,category:'视频反推 · '+r.type,projectId:r.projectId||null,requirements:'根据原片提取的参考，按本项目实际约束改编',dimensions:'待现场核对',dimensionsConfirmed:false,inventory:'库存待确认',analysis:kind==='scene'?[f.scene,f.location,f.art,f.props].filter(Boolean).join('\n'):f.costume||'',files:[...(r.video?[C.clone(r.video)]:[]),...C.clone(r.frames)],frames:C.clone(r.frames),outfits:[],proposal:C.slot('AI效果参考'),sourceReverseId:r.id};db.assets.push(a);save();route={view:'asset',id:a.id};render();notify('参考资料已保存，原片与关键帧保持来源关联。');return;}
}
function mediaMarkup(a,guides=false){if(!a)return `<div class="empty-media">尚无素材<br><small>生成成功并核验后显示</small></div>`;if(a.kind==='image')return guides?`<div class="frame"><img src="${mediaURL(a)}" alt="分镜参考"><div class="guide-v"></div><div class="guide-h"></div></div><p class="frame-label">黄色：9:16安全框　蓝色：16:9安全框（以4:3画幅为基准）</p>`:`<img class="media" src="${mediaURL(a)}" alt="视觉参考" loading="lazy">`;if(a.kind==='video')return `<video class="media" src="${mediaURL(a)}" controls preload="metadata" playsinline></video><small>实际时长 ${Number(a.duration).toFixed(2)}秒 · ${a.source==='ai'||a.source==='ai-assembly'?'AI生成':'上传素材'}</small>`;return `<a href="${mediaURL(a)}" target="_blank" rel="noopener">打开原始资料 ↗</a>`;}
function coverMediaMarkup(a,option,ratio,selected){return `<div class="cover-preview" style="aspect-ratio:${ratio==='9:16'?'9/16':'3/4'}">${a?`<img src="${mediaURL(a)}" alt="视频封面${esc(option.label)}" loading="lazy">`:'<div class="empty-media">尚无封面底图<br><small>生成或上传后显示</small></div>'}<div class="cover-shade"></div><div class="cover-copy"><strong>${esc(option.headline||'封面主标题')}</strong><span>${esc(option.subheadline||'辅助文案')}</span></div>${selected?'<b class="cover-choice">首选</b>':''}</div>`;}
function slotCard(s,path,kind,opts={}){
  const a=C.selected(s),preview=opts.cover?coverMediaMarkup(a,opts.cover,opts.ratio,opts.selected):mediaMarkup(a,opts.guides),versionIndex=a?Math.max(0,s.versions.findIndex(v=>v.id===s.selectedId))+1:0,fileName=(s.label||kind)+(kind==='image'?'.jpg':'.mp4');
  const location=a?`<div class="asset-location"><span>已回填到本卡位 · 当前第${versionIndex}版</span><span><a href="${mediaURL(a)}" target="_blank" rel="noopener">打开${kind==='image'?'原图':'视频'} ↗</a><a href="${mediaURL(a)}" download="${esc(fileName)}">下载 ↓</a></span></div>`:'';
  return `<article class="card media-card"><div class="shot-title"><h3>${esc(s.label)}</h3><small>${s.locked?'已锁定':'可打磨'}</small></div>${preview}${location}${path.includes('.quick.images.')||path.includes('.quick.videos.')?`<label>汇报借鉴要点<textarea data-field="${path}.referenceNote" class="short" placeholder="例如：借鉴侧逆光与空间层次；保留自己的服装和台词">${esc(s.referenceNote||'')}</textarea></label>`:''}<label>生成描述<textarea data-field="${path}.prompt" ${s.locked?'disabled':''}>${esc(s.prompt)}</textarea></label><div class="actions">${btn(s.task?'查询已有任务':a?'生成新版本':'生成'+(kind==='image'?'参考图':'视频'),'generate-slot',`data-path="${path}" data-kind="${kind}" data-duration="${opts.duration||8}" ${s.locked?'disabled':''}`,true)}${upload('上传'+(kind==='image'?(path.includes('.deep.')?'AI分镜图':'图片'):'AI视频'),'slot',`data-path="${path}" data-kind="${kind}" data-duration="${opts.duration||8}" ${s.locked?'disabled':''}`,kind==='image'?'image/png,image/jpeg,image/webp':'video/mp4,video/quicktime,video/webm')}${btn(s.locked?'解锁':'锁定','lock',`data-path="${path}"`)}</div>${a&&s.versions.length>1?'<p class="version-note">新版本会自动替换当前画面；旧版不删除，可在下方切回。</p>':''}${s.error?`<p class="missing">${esc(s.error)}</p>`:''}${s.versions.length?`<label>当前使用的版本<select data-version="${path}" ${s.locked?'disabled':''}>${s.versions.map((v,i)=>`<option value="${v.id}" ${s.selectedId===v.id?'selected':''}>第${i+1}版 · ${esc((v.createdAt||'').slice(0,16))}${s.selectedId===v.id?' · 当前使用':''}</option>`).join('')}</select></label><details><summary>查看所选版本的生成描述</summary><p class="preview-copy">${esc(a?.prompt||'上传参考')}</p></details>`:''}</article>`;
}
function renderTopic(t){if(!t)return empty('脚本不存在','请返回脚本列表。');if(scope==='personal'&&route.tab==='idea')return renderPersonalIdea(t);const i=ts(t),path=`topics.${i}`;const quick=route.tab!=='deep';const s=quick?(t.quick.stage==='full'?C.quickStatus(t):C.directionStatus(t)):C.deepStatus(t);return hero(quick?'QUICK REPORT':'DEVELOPMENT',t.title,quick?'先明确方向；完整交付才要求A/B/C封面、3–5张图和三段8秒AI视频。':'25镜逐张打磨，再生成完整AI成片参考。',btn('预览汇报','preview-topic',`data-id="${t.id}"`)+btn('下载PPT','export-topic',`data-id="${t.id}"`,true))+`<div class="tabs">${btn('快速汇报','topic',`data-id="${t.id}" ${quick?'class="active"':''}`)}${btn('深入优化','deep',`data-id="${t.id}" ${!quick?'class="active"':''}`)}</div>${folderBindings(t,'topic')}${readiness(s)}<div class="panel"><label>脚本名称<input data-field="${path}.title" value="${esc(t.title)}"></label><label style="margin-top:14px">原始想法与本轮修改要求<textarea data-field="${path}.idea">${esc(t.idea)}</textarea></label><label>所属项目<select data-topic-project="${t.id}"><option value="">独立脚本</option>${db.projects.map(p=>`<option value="${p.id}" ${p.id===t.projectId?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label></div>${quick?renderQuick(t,path):renderDeep(t,path)}<div class="panel"><h2>汇报反馈与版本</h2><div class="actions">${btn('记录反馈／保存版本','feedback',`data-id="${t.id}"`)}${btn('确认文字方向','approve-direction',`data-id="${t.id}"`)}${btn('确认完整交付，进入深化','approve',`data-id="${t.id}" ${!C.quickStatus(t).ready?'disabled':''}`)}</div>${t.quick.approved?`<p class="muted">方向确认于 ${esc(t.quick.approved.time)}。深化生成以此快照为依据；修改快速稿不会覆盖已确认版本。</p>`:''}<div class="list">${t.feedback.slice().reverse().map(f=>`<div class="row"><span>${esc(f.text)}</span><small>${esc(f.time.slice(0,16))}</small></div>`).join('')}${t.snapshots.slice().reverse().map(v=>`<div class="row"><span>${esc(v.note)} · ${esc(v.time.slice(0,16))}</span>${btn('查看快照','snapshot',`data-id="${t.id}" data-snapshot="${v.id}"`)}</div>`).join('')}</div></div>`;}
function renderCover(t,path){const c=C.ensureCover(t);return `<div class="section-head"><h2>视频封面推荐 · A/B/C三套</h2></div><div class="callout">封面不是从视觉参考里随便挑一张。三套方案分别测试情绪钩子、人物识别与信息转化；系统叠加可编辑文案，底图不依赖图片模型正确生成文字。</div><div class="panel"><div class="formgrid"><label>首选方案<select data-field="${path}.quick.cover.selectedId">${c.options.map(o=>`<option value="${o.id}" ${o.id===c.selectedId?'selected':''}>${o.label} · ${esc(o.angle)}</option>`).join('')}</select></label><label>封面画幅<select data-field="${path}.quick.cover.ratio"><option value="3:4" ${c.ratio==='3:4'?'selected':''}>3:4 推荐</option><option value="9:16" ${c.ratio==='9:16'?'selected':''}>9:16</option></select></label>${field('首选推荐理由',path+'.quick.cover.recommendation',c.recommendation,true)}</div></div><div class="grid cover-grid">${c.options.map((o,i)=>`<div class="panel cover-option"><div class="shot-title"><h3>${o.label} · ${esc(o.angle)}</h3>${o.id===c.selectedId?'<span class="badge">首选方案</span>':''}</div><div class="formgrid"><label>点击策略<input data-field="${path}.quick.cover.options.${i}.angle" value="${esc(o.angle)}"></label><label>封面主标题<input data-field="${path}.quick.cover.options.${i}.headline" value="${esc(o.headline)}"></label><label class="wide">辅助文案<input data-field="${path}.quick.cover.options.${i}.subheadline" value="${esc(o.subheadline)}"></label>${field('构图、信息层级与推荐逻辑',`${path}.quick.cover.options.${i}.description`,o.description,true)}</div>${slotCard(o.image,`${path}.quick.cover.options.${i}.image`,'image',{cover:o,ratio:c.ratio,selected:o.id===c.selectedId})}</div>`).join('')}</div>`;}
function renderDirectionCovers(t,path){const c=C.ensureCover(t);return `<section class="panel"><h2>方向稿 · 封面推荐（文字方案）</h2><p class="muted">方向会先讨论标题、构图与推荐理由。底图、视觉参考与视频在“完整交付”阶段制作。</p>${field('首选推荐理由',path+'.quick.cover.recommendation',c.recommendation)}<div class="grid">${c.options.map((o,i)=>`<div><h3>${o.label} · ${esc(o.angle)}</h3>${field('主标题',path+'.quick.cover.options.'+i+'.headline',o.headline,false,true)}${field('辅助文案',path+'.quick.cover.options.'+i+'.subheadline',o.subheadline,false,true)}${field('构图与点击逻辑',path+'.quick.cover.options.'+i+'.description',o.description)}</div>`).join('')}</div></section>`;}
function renderQuick(t,path){C.ensureCover(t);return `<div class="section-head"><h2>创意与故事脚本</h2><div class="actions">${btn('AI补全缺项','quick-text',`data-id="${t.id}"`)}${t.quick.stage==='full'?btn('生成全部缺失素材','quick-all',`data-id="${t.id}"`,true):''}</div></div><div class="formgrid">${C.QUICK.map(([k,label])=>field(label,path+'.quick.fields.'+k,t.quick.fields[k],k==='script')).join('')}</div>${t.quick.stage!=='full'?renderDirectionCovers(t,path):renderCover(t,path)+`<div class="section-head"><h2>视觉参考 · ${t.quick.images.length}张</h2><div class="actions">${btn('增加一张','add-image',`data-id="${t.id}" ${t.quick.images.length>=5?'disabled':''}`)}${btn('移走末张到版本记录','remove-image',`data-id="${t.id}" ${t.quick.images.length<=3?'disabled':''}`)}</div></div><div class="grid">${t.quick.images.map((s,i)=>slotCard(s,`${path}.quick.images.${i}`,'image')).join('')}</div><div class="section-head"><h2>AI视频参考 · 8秒 × 3</h2></div><div class="grid">${C.PHASES.map(([k])=>slotCard(t.quick.videos[k],`${path}.quick.videos.${k}`,'video')).join('')}</div>`}`;}
function renderDeep(t,path){return `<div class="callout">深化以已确认的汇报方向为准。AI参考采用4:3画幅，最终摄影仍需根据实际传感器画幅核对安全框。</div><div class="section-head"><h2>执行方案</h2>${btn('AI补全执行方案','deep-fields',`data-id="${t.id}"`)}</div><div class="formgrid">${C.DEEP.map(([k,label])=>field(label,path+'.deep.fields.'+k,t.deep.fields[k])).join('')}</div><div class="section-head"><h2>25镜工程</h2><div class="actions">${btn(t.deep.shots.length?'保留旧版并重拆25镜':'AI拆解25镜','deep-shots',`data-id="${t.id}"`)}${btn('补齐25张AI图','deep-images',`data-id="${t.id}"`,true)}${btn('补齐分镜视频','deep-videos',`data-id="${t.id}"`)}</div></div>${t.deep.shots.length?`<div class="list">${t.deep.shots.map((s,j)=>`<details class="panel" ${j===0?'open':''}><summary><strong>镜 ${String(j+1).padStart(2,'0')}</strong> · ${s.duration}秒 · ${esc(s.visual.slice(0,75))}</summary><div class="formgrid">${field('画面',`${path}.deep.shots.${j}.visual`,s.visual)}${field('台词与声音',`${path}.deep.shots.${j}.dialogue`,s.dialogue)}${field('景别、运镜、灯光',`${path}.deep.shots.${j}.camera`,s.camera)}<label>时长（2–12秒）<input type="number" min="2" max="12" data-number data-field="${path}.deep.shots.${j}.duration" value="${s.duration}"></label></div><div class="grid" style="margin-top:16px">${slotCard(s.image,`${path}.deep.shots.${j}.image`,'image',{guides:true})}${slotCard(s.video,`${path}.deep.shots.${j}.video`,'video',{duration:s.duration})}</div></details>`).join('')}</div>`:empty('等待拆解分镜','先确认汇报方向，再形成完整的25镜工程。')}<div class="panel"><h2>完整AI成片参考</h2><p class="muted">按25镜顺序和脚本时长合成，保留镜头声音，可叠加你上传的配乐。剪辑节奏、口型和造型连续性仍需要逐镜审片。</p><div class="actions">${btn('合成完整AI成片','assemble',`data-id="${t.id}"`,true)}${upload('上传成片配乐','bgm',`data-id="${t.id}"`,'audio/*')}</div>${t.deep.bgm?`<p>已配置配乐：${esc(t.deep.bgm.name||'音频')}</p>`:''}${t.deep.film?mediaMarkup(t.deep.film)+`<a href="${mediaURL(t.deep.film)}" download="${esc(t.title)}_AI成片.mp4">下载完整AI成片 ↧</a>`:''}</div>`;}
/* Editorial workflow: one visible next step, with details available on demand. */
function topicStep(t){if(!t.directionApproved)return 1;if(!t.quick.approved)return 2;return C.deepStatus(t).ready?4:3;}
function workflowSteps(t,current){const labels=['文字方向','完整素材','深入优化','导出交付'];return `<nav class="workflow-steps" aria-label="脚本工作流">${labels.map((label,i)=>{const n=i+1,unlocked=n===1||n===2&&!!t.directionApproved||n===3&&!!t.quick.approved||n===4&&C.deepStatus(t).ready,active=n===current;return `<button data-action="workflow-go" data-id="${t.id}" data-step="${n}" ${unlocked?'':`disabled title="完成上一步后解锁"`} class="${active?'active':''}"><span>${n}</span>${label}</button>`;}).join('')}</nav>`;}
function editorSection(title,summary,body,open=false,id=''){return `<details class="editor-section" ${id?`id="${esc(id)}"`:''} ${open?'open':''}><summary><span><strong>${title}</strong><small>${esc(summary||'待补充')}</small></span><b>编辑</b></summary><div class="editor-section-body">${body}</div></details>`;}
function quickResultStrip(t){const s=C.quickStatus(t);if(!s.covers&&!s.images&&!s.videos)return '';return `<nav class="generated-result-strip" aria-label="已生成素材位置"><strong>已生成内容在本脚本中</strong><span>点击直达：</span>${btn(`封面 ${s.covers}/3`,'reveal-material','data-target="quick-covers"')}${btn(`视觉参考 ${s.images}/${t.quick.images.length}`,'reveal-material','data-target="quick-images"')}${btn(`8秒视频 ${s.videos}/3`,'reveal-material','data-target="quick-videos"')}</nav>`;}
function topicReferenceRail(t){const project=db.projects.find(p=>p.id===t.projectId),own=StudioFolders.ids(t.folderIds),inherited=StudioFolders.ids(project?.folderIds).filter(id=>!own.includes(id)),folders=referenceFolders(),r=resolvedReferences(t);return `<aside class="evidence-rail"><section><small>参考依据</small><h3>${own.length+inherited.length?'已连接针对性审美库':'未连接项目参考'}</h3><p>${r.shared.length}项审美素材 · ${r.assets.length}项场景/服装资料</p><div class="rail-tags">${[...own,...inherited].map(id=>{const f=folders.find(x=>x.id===id);return f?`<button data-action="folder-open" data-id="${esc(id)}">${esc(f.name)}${inherited.includes(id)?' · 项目':''}</button>`:'';}).join('')||'<span>只选本条片真正需要的参考。</span>'}</div><div class="compact-actions">${btn('选择参考库','folder-bind',`data-kind="topic" data-id="${t.id}"`)}${btn('新建文件夹','folder-new',`data-owner-kind="topic" data-owner-id="${t.id}"`)}</div></section><section><small>交付标准</small><ul><li>A/B/C三套封面</li><li>3–5张视觉参考</li><li>开场/中间/结尾各8秒</li><li>25镜逐张打磨</li><li>完整AI成片参考</li></ul></section><section><small>版本</small><p>${t.feedback.length}条反馈 · ${t.snapshots.length}个快照</p>${btn('记录反馈 / 保存版本','feedback',`data-id="${t.id}"`)}</section></aside>`;}
function topicDock(t,step){const direction=C.directionStatus(t),quick=C.quickStatus(t),deep=C.deepStatus(t);let action,label;if(step===1){[action,label]=direction.ready?['approve-direction','确认方向，进入素材生成']:['quick-text','AI补全文字方案'];}else if(step===2){[action,label]=quick.ready?['approve','确认完整交付，进入深化']:['quick-all','生成全部缺失素材'];}else if(step===3){const fieldsReady=C.DEEP.every(([k])=>C.text(t.deep.fields[k]));if(!fieldsReady)[action,label]=['deep-fields','AI补全执行方案'];else if(t.deep.shots.length!==25)[action,label]=['deep-shots','AI拆解25镜'];else if(deep.images!==25)[action,label]=['deep-images','补齐25张AI分镜图'];else if(deep.videos!==25)[action,label]=['deep-videos','补齐25镜AI视频'];else [action,label]=['assemble','合成完整AI成片'];}else [action,label]=['export-topic','导出单条执行版'];const status=step===1?direction:step===2?quick:deep;return `<div class="workflow-dock">${job?`<div class="dock-job"><strong>${esc(job.title)}</strong><progress value="${job.done}" max="${job.total}"></progress><span>${job.done}/${job.total} · ${esc(job.detail||'处理中')}</span></div>`:`<div><small>当前阶段</small><strong>${step===1?'先确认创意方向':step===2?'补齐快速汇报强制素材':step===3?'深化到可执行与可预演':'所有强制交付已齐备'}</strong><span>${status.missing?.length?`还有${status.missing.length}项待完成`:'本步已就绪'}</span></div>`}<div class="actions">${btn('预览','preview-topic',`data-id="${t.id}"`)}${btn(label,action,`data-id="${t.id}"`,true)}</div></div>`;}
function renderTopic(t){if(!t)return empty('脚本不存在','请返回脚本列表。');if(scope==='personal'&&route.tab==='idea')return renderPersonalIdea(t);const i=ts(t),path=`topics.${i}`,allowed=topicStep(t);let step=route.tab==='direction'?1:route.tab==='deep'?3:(t.quick.stage==='full'||t.directionApproved?2:1);if(step>allowed)step=allowed;if(allowed===4&&route.tab==='deep')step=4;t.quick.stage=step===1?'direction':'full';const report=StudioPpt.ensureReport(t),status=step===1?C.directionStatus(t):step===2?C.quickStatus(t):C.deepStatus(t);return `${workflowSteps(t,step)}<header class="editor-hero"><div><span>${step===1?'方向汇报 · 3小时响应':step===2?'快速汇报 · 完整交付':step===3?'单条执行 · 深入优化':'交付中心'}</span><h1>${esc(t.title)}</h1><p>${esc(report.recommendation||t.quick.fields.outline||t.idea||'从一句想法开始，由AI补全成可汇报的创意方向。')}</p></div><div class="editor-hero-actions">${btn('编辑项目设定','topic-settings',`data-id="${t.id}"`)}${btn('汇报要点','report-refine',`data-id="${t.id}" data-kind="topic"`)}</div></header><div class="editor-status ${status.ready?'ready':''}"><strong>${status.ready?'本阶段已就绪':'继续打磨'}</strong><span>${status.missing?.length?esc(status.missing.slice(0,4).join(' · '))+(status.missing.length>4?` 等${status.missing.length}项`:''):'可进入下一步'}</span></div>${step===2?quickResultStrip(t):''}<div class="editor-layout"><main class="editor-document">${step<=2?renderQuick(t,path,step):renderDeep(t,path)}<details class="editor-section version-section"><summary><span><strong>反馈与版本</strong><small>保留每次方向确认和修改记录</small></span><b>查看</b></summary><div class="editor-section-body list">${t.feedback.slice().reverse().map(f=>`<div class="row"><span>${esc(f.text)}</span><small>${esc(f.time.slice(0,16))}</small></div>`).join('')}${t.snapshots.slice().reverse().map(v=>`<div class="row"><span>${esc(v.note)} · ${esc(v.time.slice(0,16))}</span>${btn('查看快照','snapshot',`data-id="${t.id}" data-snapshot="${v.id}"`)}</div>`).join('')||'<p class="muted">尚无版本记录。</p>'}</div></details></main>${topicReferenceRail(t)}</div>${topicDock(t,step)}`;}
function renderQuick(t,path,step){C.ensureCover(t);const f=t.quick.fields;return `<div class="document-intro"><small>内容总监建议</small><h2>${esc(f.outline||'请先建立一个能被一句话讲清的创意主张。')}</h2><p>${esc(f.meaning||'寓意、人物动机和观众情绪会在这里被提炼。')}</p></div>${editorSection('核心创意与寓意',f.outline,field('创意大纲',path+'.quick.fields.outline',f.outline,true)+field('创意寓意',path+'.quick.fields.meaning',f.meaning,true)+field('创意描述',path+'.quick.fields.description',f.description,true),true)}${editorSection('故事脚本与台词',f.script||f.dialogue,field('完整故事脚本',path+'.quick.fields.script',f.script,true)+field('台词',path+'.quick.fields.dialogue',f.dialogue,true))}${editorSection('影像与摄影方向',f.atmosphere||f.camera,field('影像氛围参考',path+'.quick.fields.atmosphere',f.atmosphere,true)+field('摄影调性参考',path+'.quick.fields.camera',f.camera,true))}${step===1?editorSection('封面方向',C.ensureCover(t).recommendation,renderDirectionCovers(t,path)):renderQuickMaterials(t,path)}`;}
function renderQuickMaterials(t,path){const s=C.quickStatus(t);return `${editorSection('封面推荐 · A/B/C',C.ensureCover(t).recommendation,renderCover(t,path),s.covers>0,'quick-covers')}${editorSection(`视觉参考 · ${s.images}/${t.quick.images.length}张`,'生成图会自动回填到下方对应卡位',`<div class="section-head compact"><div></div><div class="actions">${btn('增加一张','add-image',`data-id="${t.id}" ${t.quick.images.length>=5?'disabled':''}`)}${btn('移走末张','remove-image',`data-id="${t.id}" ${t.quick.images.length<=3?'disabled':''}`)}</div></div><div class="grid">${t.quick.images.map((slot,i)=>slotCard(slot,`${path}.quick.images.${i}`,'image')).join('')}</div>`,s.images>0,'quick-images')}${editorSection(`AI视频参考 · ${s.videos}/3段`,'开场、中间、结尾各8秒',`<div class="grid">${C.PHASES.map(([k])=>slotCard(t.quick.videos[k],`${path}.quick.videos.${k}`,'video')).join('')}</div>`,s.videos>0,'quick-videos')}`;}
function renderDeep(t,path){const f=t.deep.fields,s=C.deepStatus(t);return `<div class="document-intro"><small>执行化原则</small><h2>所有深化均以已确认的快速汇报为准。</h2><p>AI参考采用4:3 Open Gate，兼顾中央9:16主输出和16:9保底；最终安全框仍须按实际机型核对。</p></div>${editorSection('人物、场景与美术',f.acting||f.location,field('表演与人物',path+'.deep.fields.acting',f.acting,true)+field('场地与尺寸约束',path+'.deep.fields.location',f.location,true)+field('美术制景',path+'.deep.fields.art',f.art,true)+field('道具',path+'.deep.fields.props',f.props,true)+field('服装妆造',path+'.deep.fields.costume',f.costume,true),true)}${editorSection('影像、灯光与声音',f.camera||f.lighting,field('灯光',path+'.deep.fields.lighting',f.lighting,true)+field('摄影与画幅',path+'.deep.fields.camera',f.camera,true)+field('台词、音乐与音效',path+'.deep.fields.sound',f.sound,true)+field('剪辑与转场',path+'.deep.fields.edit',f.edit,true))}${editorSection('资源、排期与风险',f.schedule||f.budget,field('预算与资源',path+'.deep.fields.budget',f.budget,true)+field('拍摄排期',path+'.deep.fields.schedule',f.schedule,true)+field('可行性与待确认事项',path+'.deep.fields.risks',f.risks,true))}${editorSection(`25镜工程 · ${t.deep.shots.length}/25`,`${s.images}/25张AI图 · ${s.videos}/25段AI视频`,t.deep.shots.length?`<div class="list">${t.deep.shots.map((shot,j)=>`<details class="shot-editor" ${j===0?'open':''}><summary><strong>镜 ${String(j+1).padStart(2,'0')}</strong><span>${shot.duration}秒 · ${esc(shot.visual.slice(0,70))}</span></summary><div class="formgrid">${field('画面',`${path}.deep.shots.${j}.visual`,shot.visual)}${field('台词与声音',`${path}.deep.shots.${j}.dialogue`,shot.dialogue)}${field('景别、运镜、灯光',`${path}.deep.shots.${j}.camera`,shot.camera)}<label>时长（2–12秒）<input type="number" min="2" max="12" data-number data-field="${path}.deep.shots.${j}.duration" value="${shot.duration}"></label></div><div class="grid shot-media">${slotCard(shot.image,`${path}.deep.shots.${j}.image`,'image',{guides:true})}${slotCard(shot.video,`${path}.deep.shots.${j}.video`,'video',{duration:shot.duration})}</div></details>`).join('')}</div>`:'<div class="empty compact-empty"><h3>尚未拆解分镜</h3><p>执行方案齐备后，下一步会形成完整25镜。</p></div>')}${editorSection('完整AI成片参考',t.deep.film?'已生成可审片成片':'等待25镜全部完成',`<p class="muted">按25镜顺序和脚本时长合成，保留镜头声音，可叠加配乐。口型、造型连续性和剪辑节奏仍需逐镜审片。</p><div class="actions">${upload('上传成片配乐','bgm',`data-id="${t.id}"`,'audio/*')}</div>${t.deep.bgm?`<p>已配置配乐：${esc(t.deep.bgm.name||'音频')}</p>`:''}${t.deep.film?mediaMarkup(t.deep.film)+`<a href="${mediaURL(t.deep.film)}" download="${esc(t.title)}_AI成片.mp4">下载完整AI成片 ↧</a>`:''}`)}`;}

function reverseProgress(r){const current=!r.video?1:r.frames.length<12?2:!r.analysis?3:4,labels=['导入原片','提取证据','反推创意','沉淀资料'];return `<ol class="reverse-progress">${labels.map((label,i)=>`<li class="${i+1===current?'active':''} ${i+1<current?'done':''}"><span>${i+1}</span>${label}</li>`).join('')}</ol>`;}
function reverseGroup(title,summary,fields,path,open=false){return editorSection(title,summary,fields.map(([k,label])=>field(label,`${path}.analysis.fields.${k}`,get(`${path}.analysis.fields.${k}`)||'',true)).join(''),open);}
function renderReverse(){const q=(route.query||'').toLowerCase(),rows=db.reverse.filter(r=>(r.title+' '+r.type+' '+(r.analysis?.fields.outline||'')).toLowerCase().includes(q));return hero('VIDEO TO CREATIVE','视频反推创意','从成片中重建创作意图、核心概念、脚本与可复用方法。',btn('建立视频反推','reverse-new','',true))+`<div class="reverse-library-bar"><label><span>搜索反推资产</span><input data-reverse-search value="${esc(route.query||'')}" placeholder="标题、类型或创意概念"></label><p>喜欢的参考片与历史项目分开标记；AI推测与可见事实始终分开保存。</p></div><div class="reverse-list">${rows.map(r=>{const f=r.analysis?.fields||{},stage=!r.video?'待上传':r.frames.length<12?'待提帧':!r.analysis?'待反推':'已形成资产';return `<article class="reverse-card"><div><span class="badge">${r.purpose==='archive'?'历史项目重建':'喜欢的参考片'}</span><small>${esc(r.type)} · ${stage}</small></div><h3>${esc(r.title)}</h3><p>${esc(f.concept||f.outline||r.notes||'上传原片后，系统将用关键帧与你补充的资料建立可核对的反推档案。')}</p><div class="reverse-card-meta"><span>${r.frames.length}/12证据帧</span><span>${r.supportingFiles?.length||0}份补充资料</span>${btn('继续','reverse-open',`data-id="${r.id}"`,true)}</div></article>`;}).join('')||empty('建立第一个反推案例','上传喜欢的参考片，或从一个历史项目成片开始。')}</div>`;}
function renderReverseDetail(r){if(!r)return empty('反推记录不存在','请返回视频反推创意。');const path='reverse.'+db.reverse.indexOf(r),a=r.analysis,f=a?.fields||{};return `${reverseProgress(r)}<header class="editor-hero reverse-hero"><div><span>${r.purpose==='archive'?'历史项目重建':'参考片拆解'}</span><h1>${esc(r.title)}</h1><p>${esc(f.concept||f.intent||r.notes||'先建立来源和证据，再让AI区分可见事实、创意推断和未知事项。')}</p></div><div class="editor-hero-actions">${btn('返回反推库','nav','data-view="reverse"')}</div></header><div class="editor-layout reverse-layout"><main class="editor-document">${editorSection('项目设定与你的已知信息',r.notes||'标注你为什么喜欢，或当时的项目背景',`<div class="formgrid"><label>标题<input data-field="${path}.title" value="${esc(r.title)}"></label><label>反推用途<select data-field="${path}.purpose"><option value="reference" ${r.purpose==='reference'?'selected':''}>喜欢的参考片</option><option value="archive" ${r.purpose==='archive'?'selected':''}>已完成的历史项目</option></select></label><label>类型／分类<input data-field="${path}.type" value="${esc(r.type)}"></label><label>关联项目<select data-field="${path}.projectId"><option value="">独立反推</option>${db.projects.map(p=>`<option value="${p.id}" ${p.id===r.projectId?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label>${field(r.purpose==='archive'?'已知项目背景、当时目标、你负责的内容':'为什么喜欢、希望理解或借鉴什么',path+'.notes',r.notes,true)}${field('你核对过的台词／字幕／声音说明',path+'.transcript',r.transcript,true)}</div>`,true)}${editorSection('原片、来源与补充资料',r.video?'原片已保存，可继续补充旧脚本、海报或现场照':'可手动上传或解析公开链接',`${reverseSupportHTML(r,path)}<div class="actions">${upload(r.video?'替换原片':'上传原视频','reverse-video',`data-id="${r.id}"`,'video/mp4,video/quicktime,video/webm')}</div>${r.video?mediaMarkup(r.video):''}`)}${editorSection('声音与证据核对',`${r.frames.length}/12个关键帧 · ${(r.transcriptions||[]).length}份转写候选`,`<div class="actions">${btn('重新提取12个候选关键帧','reverse-frames',`data-id="${r.id}" ${!r.video?'disabled':''}`)}${btn('豆包转写原片音轨','reverse-transcribe',`data-id="${r.id}" ${!r.video||!r.video.hasAudio?'disabled':''}`)}</div><p class="muted">均匀采样不是逐镜检测；转写先作为候选，不会覆盖你核对过的文字。</p>${reverseTranscriptionHTML(r)}${r.error?`<p class="missing">${esc(r.error)}</p>`:''}`)}${a?`${reverseGroup('创意结论',f.concept||f.intent,[['intent','创作意图（推测）'],['concept','核心创作概念'],['outline','创意大纲'],['meaning','创意寓意（推测）'],['reuse','可复用创意与改编方向']],path,true)}${reverseGroup('重建脚本',f.script||f.description,[['description','创意描述与叙事结构'],['script','重建故事脚本'],['dialogue','台词／字幕依据']],path)}${reverseGroup('拍摄执行',f.atmosphere||f.camera,[['scene','场景'],['location','场地'],['art','美术制景'],['props','道具'],['atmosphere','影像氛围'],['camera','摄影调性'],['music','配乐与声音（待核对）'],['costume','服装造型']],path)}${reverseGroup('归档与未确认事项',f.archive||f.uncertainties,[['archive','可沉淀的历史成果与资料'],['uncertainties','未确认事项与采样限制']],path)}${editorSection(`关键画面拆解 · ${(a.shots||[]).length}条`,'不冒充完整切镜表',`<div class="list">${(a.shots||[]).map((s,i)=>`<details class="shot-editor"><summary><strong>证据 ${i+1}</strong><span>${s.timestamp}秒 · ${esc(s.visual.slice(0,70))}</span></summary><div class="formgrid">${field('画面',path+`.analysis.shots.${i}.visual`,s.visual)}${field('摄影',path+`.analysis.shots.${i}.camera`,s.camera)}${field('台词依据',path+`.analysis.shots.${i}.dialogue`,s.dialogue)}${field('依据与限制',path+`.analysis.shots.${i}.note`,s.note)}</div></details>`).join('')}</div>`)}`:''}</main><aside class="evidence-rail reverse-evidence"><section><small>原片证据</small><h3>${r.video?'原视频已安全保存':'尚未上传原片'}</h3>${r.video?mediaMarkup(r.video):'<p>上传视频后才会启动看图分析。</p>'}</section><section><small>关键帧</small><div class="evidence-thumbs">${r.frames.slice(0,4).map((frame,i)=>`<figure>${mediaMarkup(frame)}<figcaption>${frame.timestamp}秒</figcaption></figure>`).join('')||'<p>尚无画面证据</p>'}</div>${r.frames.length>4?`<p>共${r.frames.length}张，仅在需要核对时展开。</p>`:''}</section>${a?`<section><small>分析依据</small><p>${esc(a.basis)}</p><p>${esc(f.uncertainties||'')}</p></section><section><small>沉淀为资产</small><div class="compact-actions">${btn('保存完整反推档案','reverse-reference',`data-id="${r.id}"`,true)}${btn('保存场景参考','reverse-scene',`data-id="${r.id}"`)}${btn('保存服装参考','reverse-wardrobe',`data-id="${r.id}"`)}</div></section>`:''}</aside></div><div class="workflow-dock reverse-dock"><div><small>当前任务</small><strong>${!r.video?'先建立原片证据':r.frames.length<12?'提取可核对的关键画面':!a?'生成创意与脚本反推':'将成果变成可复用资产'}</strong><span>${r.error?esc(r.error):'所有推断都保留依据与不确定性'}</span></div><div class="actions">${!r.video?upload('上传原视频','reverse-video',`data-id="${r.id}"`,'video/mp4,video/quicktime,video/webm'):r.frames.length<12?btn('提取12个候选关键帧','reverse-frames',`data-id="${r.id}"`,true):!a?btn('AI反推创意与脚本','reverse-analyze',`data-id="${r.id}"`,true):btn('重新反推并替换','reverse-analyze',`data-id="${r.id}"`)+btn('保存为新选题','reverse-topic',`data-id="${r.id}"`,true)}</div></div>`;}

function renderProject(p){
  if(!p)return empty('专场不存在','请返回专场列表。');if(isPersonalProject(p))return renderPersonalProject(p);
  const path=`projects.${ps(p)}`,s=C.sessionStatus(p,db.topics),target=C.sessionTarget(p),direction=p.stage!=='full';
  return hero('SESSION REPORT',p.title,`计划${target}条片 · ${direction?'方向阶段：先明确主张与各条分工，不强制生成媒体':'完整交付：每条脚本、A/B/C封面、3–5张图、三段8秒AI视频'}`,btn('预览整体汇报','preview-project',`data-id="${p.id}"`)+btn('下载专场PPT','export-project',`data-id="${p.id}"`,true))+folderBindings(p,'project')+readiness(direction?C.directionStatus(p,'project',db.topics):s)+`<div class="panel"><div class="formgrid"><label>专场名称<input data-field="${path}.title" value="${esc(p.title)}"></label><label>直播日期<input type="date" data-field="${path}.date" value="${esc(p.date)}"></label><label>计划片数（1–100，不自动删除已有脚本）<input type="number" min="1" max="100" data-session-count="${p.id}" value="${target}"></label>${field('专场目标、受众、主题与内容组合要求',path+'.idea',p.idea,true)}</div></div><div class="section-head"><h2>整体方向与策划</h2>${btn('AI补全整体方向与缺少的故事','project-text',`data-id="${p.id}"`,true)}</div><p class="muted">此按钮只生成文字，已有内容不覆盖。请在需求里明确各类型数量；与计划片数冲突时需先核对。</p><div class="formgrid">${C.SESSION.map(([k,label])=>field(label,path+'.fields.'+k,p.fields[k])).join('')}</div><div class="section-head"><h2>故事分工 · ${s.items.length}/${target}条</h2><div class="actions">${btn('关联已有脚本','link-topics',`data-id="${p.id}"`)}${!direction?btn('批量补齐完整交付素材','project-all',`data-id="${p.id}"`,true):''}</div></div><div class="grid">${s.items.map(topicCard).join('')}</div><div class="section-head"><h2>本专场场景与服装</h2>${btn('上传项目资料','new-asset',`data-project="${p.id}"`)}</div><div class="grid">${db.assets.filter(a=>a.projectId===p.id).map(assetCard).join('')||empty('还没有项目资料','上传场地尺寸图、实景或过往视频，帮助生成更贴近实际的方案。')}</div>`;
}
function assetCard(a){return `<article class="card"><span class="badge">${a.kind==='scene'?'场景':a.kind==='wardrobe'?'服装':'审美参考'} · ${esc(a.category||'未分类')}</span><h3>${esc(a.name)}</h3><p>${esc(a.requirements||'上传参考，积累个人审美')}</p>${btn('查看与打磨','asset',`data-id="${a.id}"`)}</article>`;}
function globalAssets(){return loadAesthetic();}
function renderLibrary(){const kind={scenes:'scene',wardrobe:'wardrobe',aesthetic:'aesthetic'}[route.view];const title={scene:'场景库',wardrobe:'服装库',aesthetic:'审美参考库'}[kind];const assets=kind==='aesthetic'?globalAssets():db.assets.filter(a=>a.kind===kind);return hero('CREATIVE ASSETS',title,kind==='scene'?'真实场地尺寸、已有参考与AI布景方案。':kind==='wardrobe'?'过往视频归档、造型提取和项目搭配推荐。':'当前空间独立保存审美积累。',btn('建立资料专题','new-asset',`data-kind="${kind}"`,true))+`<div class="grid">${assets.map(a=>assetCard(a).replace('data-action="asset"','data-action="'+(kind==='aesthetic'?'global-asset':'asset')+'"')).join('')||empty('建立第一个专题','可以先创建资料卡，再上传图片、尺寸图和视频。')}</div>`;}
function renderAsset(a){if(!a)return empty('资料不存在','返回资料库继续。');const path='assets.'+db.assets.indexOf(a);const p=db.projects.find(p=>p.id===a.projectId);return hero('PROJECT REFERENCES',a.name,`${esc(a.category||'未分类')} · ${esc(p?.title||'未关联专场')}`,btn('返回资料库','nav','data-view="aesthetic"'))+folderMembership(a,'asset')+`<div class="panel"><div class="formgrid"><label>专题名称<input data-field="${path}.name" value="${esc(a.name)}"></label><label>分类／标签<input data-field="${path}.category" value="${esc(a.category)}"></label><label>所属项目<select data-field="${path}.projectId"><option value="">不关联</option>${db.projects.map(p=>`<option value="${p.id}" ${p.id===a.projectId?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label>${field('想要的场景／搭配效果、参考重点',path+'.requirements',a.requirements,true)}${a.kind==='scene'?field('场地尺寸、层高、柱位、出入口、电源与搭建限制',path+'.dimensions',a.dimensions,true)+`<label><input type="checkbox" data-bool data-field="${path}.dimensionsConfirmed" ${a.dimensionsConfirmed?'checked':''}> 我已核对以上尺寸，图上不清楚的部分已标注</label>`:field('服装库存、尺码、存放位置、采购／租赁条件',path+'.inventory',a.inventory,true)}</div></div><div class="section-head"><h2>原始资料</h2>${upload('上传尺寸图／参考／视频','asset',`data-id="${a.id}"`,'image/png,image/jpeg,image/webp,video/mp4,video/quicktime,video/webm,application/pdf')}</div><p class="muted">单文件最多250MB。PDF可归档；AI识图请另外上传清晰的尺寸图截图。</p><div class="grid">${a.files.map((f,i)=>`<div class="card media-card">${mediaMarkup(f)}<small>${esc(f.name)}</small>${f.kind==='video'?btn('提取12个候选关键帧','frames',`data-id="${a.id}" data-file="${i}"`):''}</div>`).join('')}</div><div class="section-head"><h2>${a.kind==='scene'?'场地分析与可落地方案':'造型识别与搭配建议'}</h2><div class="actions">${btn(a.kind==='scene'?'AI分析场地与参考':'AI识别关键帧服装','analyze-asset',`data-id="${a.id}"`,true)}</div></div><div class="panel">${field('分析与执行建议（可修改，未核实内容须保留标注）',path+'.analysis',a.analysis)}${a.kind==='wardrobe'?`<p class="muted">关键帧采用均匀采样，可能遗漏换装瞬间。可追加视频或上传你截取的清晰画面。</p><div class="grid">${(a.outfits||[]).map((o,i)=>`<div class="card">${mediaMarkup(a.frames[o.frameIndex])}<h3>${esc(o.name)}</h3><p>${esc(o.description)}</p><p>${esc(o.recommendation)}</p><p class="muted">来源时间点：${a.frames[o.frameIndex]?.timestamp??'手动上传'}秒</p><label><input type="checkbox" data-bool data-field="${path}.outfits.${i}.selected" ${o.selected?'checked':''}> 选为本项目造型依据</label></div>`).join('')}</div>`:''}</div><div class="section-head"><h2>${a.kind==='scene'?'场景效果参考':'搭配效果参考'}</h2></div>${slotCard(a.proposal,path+'.proposal','image')}<p class="muted">原图与AI效果分别保存。场景效果图用于沟通，未经现场核实不能作为施工图。</p>`;}
function renderArchive(){return hero('DELIVERABLES','成果与备份','PPT和素材保存在生成成果中，可重复下载。备份包只包含当前空间及它的审美资料。',btn('导出完整备份ZIP','backup','',true)+upload('导入备份（当前空间副本）','restore','','application/zip'))+`<div class="panel"><h2>固定汇报模板</h2><p class="muted">参考你提供的《决战双十一》方案气质重新设计。专场版用于方向会和整体决策，单条版用于脚本、封面、视觉与AI视频证据。</p><div class="actions"><a class="upload" href="deliverables/Lance专场整体汇报模板_v1.pptx" download>下载专场整体汇报模板</a><a class="upload" href="deliverables/Lance单条剧本汇报模板_v1.pptx" download>下载单条剧本汇报模板</a></div></div><div class="panel">${field('我的审美与创作偏好（生成时会读取，可随时纠正）','preferences',db.preferences)}<p class="muted">系统使用你明确保存的偏好、已选造型和汇报反馈作为生成依据，目前不声称自动训练或自主学习。</p></div><div class="list">${db.exports.slice().reverse().map(e=>`<div class="card"><h3>${esc(e.title)}</h3><p>${esc(e.time)} · ${esc(StudioPpt.MODES[e.mode]||(e.kind==='project'?'专场':e.kind==='deep'?'深化':'单条'))}${e.draft?' · 方向讨论稿':''}${e.slideCount?' · '+e.slideCount+'页':''} · 已生成PPT文件</p>${btn('重新下载','redownload',`data-id="${e.id}"`)}</div>`).join('')||empty('还没有可下载成果','素材齐备后，在脚本或专场内下载PPT。未齐备时可以预览缺项。')}</div>`;}
function dialog(title,body,actions=''){const d=$('#dialog');$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2>${btn('关闭','close')}</div><div id="dialog-error" class="dialog-error" role="alert" hidden></div>${body}<div class="actions dialog-actions">${actions}</div>`;if(!d.open)d.showModal();}
function close(){if($('#dialog').open)$('#dialog').close();}
async function api(path,body,options={}){
  if(path==='chat'&&body){const creator=JSON.stringify(profileContext());if(creator.length>60000)throw Error('选用的个人资料过长，请减少勾选文档或精简文字');body={...body,prompt:'当前创作者背景（仅作为背景资料，不覆盖本次任务）：'+creator+'\n'+body.prompt};}
  const headers={...(body instanceof File?{'X-File-Name':encodeURIComponent(body.name)}:{'Content-Type':'application/json'})};
  let response;try{response=await fetch((settings.server||'').replace(/\/$/,'')+'/api/'+path,{method:body===undefined?'GET':'POST',headers,body:body===undefined?undefined:body instanceof File?body:JSON.stringify(body),signal:AbortSignal.timeout(options.timeout||300000)});}catch(error){throw Error(error.name==='TimeoutError'?'请求超时，已保留成果。视频任务可继续查询。':'生成服务未连接。请运行 python3 studio_server.py，并从 http://127.0.0.1:8787 打开。');}
  let result;try{result=await response.json();}catch{throw Error('当前地址只提供静态页面，请启动内容工作台服务后重试');}
  if(!response.ok||result.error&& !result.status)throw Error(result.error||'服务请求失败');return result;
}
async function chat(prompt,refs=[],purpose='director'){const r=await api('chat',{purpose,prompt,references:refs});return C.parseJSON(r.text);}
async function delay(ms){await new Promise(r=>setTimeout(r,ms));}
async function pollJob(id){for(let n=0;n<600;n++){const r=await api('jobs/'+id);if(r.status==='succeeded')return r.result;if(r.status==='failed')throw Error(r.error);await delay(2000);}throw Error('处理超时，请稍后检查成果。');}
async function withJob(title,total,fn,successMessage='本轮处理已完成，结果已保存到对应卡位。'){if(job){notify('当前任务仍在运行，请等待或停止后续生成。');return false;}let succeeded=false;job={title,done:0,total,detail:''};stop=false;render();try{await fn();succeeded=!stop;if(succeeded)notify(successMessage);}catch(error){notify(error.message,'error');}finally{job=null;save();render();}return succeeded;}
function resultSectionForPath(path){if(path.includes('.quick.cover.'))return 'quick-covers';if(path.includes('.quick.images.'))return 'quick-images';if(path.includes('.quick.videos.'))return 'quick-videos';return '';}
function revealResult(id){if(!id)return;const section=document.getElementById(id);if(!section)return;section.open=true;section.scrollIntoView({behavior:'smooth',block:'start'});}
function progress(detail){if(!job)return;job.detail=detail;job.done++;save();render();}
async function ensureService(){health=await api('health');if(!health.ffmpeg)throw Error('缺少FFmpeg，无法验证视频时长和保存媒体，请先安装后重试。');}
function quickPrompt(t){return `根据以下资料补全单条快速汇报。遵守已确认方向，不统一套用史诗风格。脚本应有完整起承转合与台词，所有产品性能、人物事实必须有依据或标为待确认。参考图、封面与视频用于汇报，不以文字提示词代替最终媒体。封面必须给出A/B/C三套不同点击逻辑，分别侧重情绪钩子、人物识别、信息转化；标题简短有记忆点，辅助文案补足直播日期或行动信息。封面prompt只描述无字底图，给后期标题留安全区，禁止让图片模型生成任何文字、字母、数字或水印。\n${JSON.stringify(context(t))}\n只返回JSON：{"fields":${JSON.stringify(Object.fromEntries(C.QUICK.map(([k,l])=>[k,l])))},"cover":{"recommendation":"首选方案和依据","recommendedIndex":0,"options":[恰好3个对象，每个{"headline":"封面主标题","subheadline":"辅助文案","description":"构图、信息层级和点击逻辑","prompt":"竖版无字封面底图详细描述，明确人物位置和标题安全区"}]},"imagePrompts":[恰好${t.quick.images.length}条详细视觉描述],"videoPrompts":{"opening":"开场独立8秒，明确镜头、动作、声音和节奏","middle":"中间独立8秒","ending":"结尾独立8秒"}}` ;}
async function generateQuickText(t){const parsed=C.validateQuick(await chat(quickPrompt(t),referenceIDs(t)),t.quick.images.length);C.snapshot(t,'AI补全前的快速汇报');for(const[k]of C.QUICK)if(!C.text(t.quick.fields[k]))t.quick.fields[k]=parsed.fields[k];const cover=C.ensureCover(t);if(!C.text(cover.recommendation))cover.recommendation=parsed.cover.recommendation;cover.selectedId=cover.options[parsed.cover.recommendedIndex].id;cover.options.forEach((o,i)=>{const candidate=parsed.cover.options[i];if(!C.text(o.headline))o.headline=candidate.headline;if(!C.text(o.subheadline))o.subheadline=candidate.subheadline;if(!C.text(o.description))o.description=candidate.description;if(!o.image.locked&&!C.text(o.image.prompt))o.image.prompt=candidate.prompt;});t.quick.images.forEach((s,i)=>{if(!s.locked&&!C.text(s.prompt))s.prompt=parsed.imagePrompts[i];});for(const[k]of C.PHASES)if(!t.quick.videos[k].locked&&!C.text(t.quick.videos[k].prompt))t.quick.videos[k].prompt=parsed.videoPrompts[k];save();}
function ownerOf(path){return path.startsWith('topics.')?db.topics[Number(path.split('.')[1])]:null;}
function refreshReadiness(){const target=$('#view > .rule'),t=currentTopic(),p=currentProject();if(target&&(t||p))target.outerHTML=readiness(t?(route.tab==='deep'?C.deepStatus(t):t.quick.stage==='full'?C.quickStatus(t):C.directionStatus(t)):p.stage==='full'?C.sessionStatus(p,db.topics):C.directionStatus(p,'project',db.topics));const approve=$('[data-action="approve"]');if(approve&&t)approve.disabled=!C.quickStatus(t).ready;if(route.view==='topic'&&t&&$('.workflow-dock')){const allowed=topicStep(t);let step=route.tab==='direction'?1:route.tab==='deep'?3:(t.quick.stage==='full'||t.directionApproved?2:1);if(step>allowed)step=allowed;if(allowed===4&&route.tab==='deep')step=4;const status=step===1?C.directionStatus(t):step===2?C.quickStatus(t):C.deepStatus(t),box=$('.editor-status');if(box)box.outerHTML=`<div class="editor-status ${status.ready?'ready':''}"><strong>${status.ready?'本阶段已就绪':'继续打磨'}</strong><span>${status.missing?.length?esc(status.missing.slice(0,4).join(' · '))+(status.missing.length>4?` 等${status.missing.length}项`:''):'可进入下一步'}</span></div>`;$('.workflow-dock').outerHTML=topicDock(t,step);}}
function deepPreviewHTML(t){return readiness(C.deepStatus(t))+C.DEEP.map(([k,l])=>`<div class="preview-block"><h2>${l}</h2><p class="preview-copy">${esc(t.deep.fields[k]||'待补充')}</p></div>`).join('')+t.deep.shots.map((s,i)=>`<div class="preview-block"><h2>镜 ${i+1} · ${s.duration}秒</h2><p>${esc(s.visual)}</p><p>${esc(s.dialogue)}</p><p>${esc(s.camera)}</p>${mediaMarkup(C.selected(s.image),true)}</div>`).join('')+`<h2>完整AI成片参考</h2>${mediaMarkup(t.deep.film)}`;}
async function generateSlot(path,kind,duration=8){
  const slot=get(path);if(slot.locked)throw Error('参考已锁定，请先解锁');if(!C.text(slot.prompt))throw Error('请先填写该素材的生成描述');const t=ownerOf(path);const asset=path.startsWith('assets.')?db.assets[Number(path.split('.')[1])]:null;
  const refs=asset?[...asset.files.filter(f=>f.kind==='image'),...(asset.frames||[]).filter((_,i)=>(asset.outfits||[]).some(o=>o.selected&&o.frameIndex===i))].map(f=>f.localId).slice(0,4):t?referenceIDs(t):[];
  const prompt=slot.prompt+'\n保持同一人物、产品、服装与场景。'+(t?'项目资料：'+JSON.stringify(context(t)):'场地或服装资料：'+JSON.stringify({dimensions:asset?.dimensions,dimensionsConfirmed:asset?.dimensionsConfirmed,analysis:asset?.analysis,requirements:asset?.requirements}));
  try{
    let result;
    if(kind==='image'){const prior=C.selected(slot);const editRefs=[...(C.assetOK(prior,'image')?[prior.localId]:[]),...refs];const isCover=path.includes('.quick.cover.options.');const coverRatio=isCover?C.ensureCover(t).ratio:null;const coverRule=isCover?`\n这是${coverRatio}竖版视频封面底图。画面必须有清晰单一视觉主体，并为后期主标题和辅助文案保留安全区。不要生成任何文字、字母、数字、标识或水印，文案由系统后期叠加。`:'';result=await api('image',{prompt:prompt+coverRule+(prior?'\n第一张参考是当前版本，请按本轮描述修改，并保留没有要求变化的主体与空间关系。':''),references:[...new Set(editRefs)].slice(0,4),size:isCover?(coverRatio==='9:16'?'1440x2560':'1728x2304'):undefined});}
    else{
      let reference=null;
      if(path.includes('.deep.shots.')){const shot=t.deep.shots[Number(path.split('.')[4])];reference=C.selected(shot.image)?.localId;}
      else if(t){const k=path.split('.').at(-1);const index={opening:0,middle:1,ending:t.quick.images.length-1}[k];reference=C.selected(t.quick.images[index])?.localId;}
      if(!reference)throw Error('请先生成或上传对应参考图，再生成视频以保持造型一致');
      if(!slot.task){const submission=await api('video',{prompt,reference,duration,ratio:'4:3'});slot.task={id:submission.taskId,duration,startedAt:new Date().toISOString()};save();}
      for(let attempt=0;attempt<450;attempt++){
        if(stop){slot.error='查询已暂停，任务ID已保存。再次点击将继续查询，不重复提交。';save();return;}
        const status=await api('video/status',{taskId:slot.task.id});
        if(status.status==='succeeded'){result=status.asset;break;}
        if(['failed','expired','cancelled'].includes(status.status)){slot.task=null;throw Error(status.error||'视频任务失败，请重试');}
        await delay(2000);
      }
      if(!result)throw Error('视频仍在排队。任务ID已保留，稍后点击继续查询。');
      if(Math.abs(result.duration-duration)>0.15){slot.task=null;throw Error(`视频实际为${result.duration.toFixed(2)}秒，不满足${duration}秒要求。请调整视频模型后重试。`);}
    }
    C.putVersion(slot,result);save(); // Keep prior film accessible; fingerprint marks it out of date.
  }catch(error){slot.error=error.message;save();throw error;}
}
async function quickAll(t){const cover=C.ensureCover(t);const coverMissing=!C.text(cover.recommendation)||cover.options.some(o=>!C.text(o.headline)||!C.text(o.subheadline)||!C.text(o.description)||!C.text(o.image.prompt));if(C.QUICK.some(([k])=>!C.text(t.quick.fields[k]))||coverMissing||t.quick.images.some(s=>!C.text(s.prompt))||C.PHASES.some(([k])=>!C.text(t.quick.videos[k].prompt)))await generateQuickText(t);progress('创意内容和封面策略已检查');const path='topics.'+ts(t);const errors=[];for(let i=0;i<cover.options.length;i++){if(stop)break;const s=cover.options[i].image;if(!C.assetOK(C.selected(s),'image')){try{await generateSlot(`${path}.quick.cover.options.${i}.image`,'image');}catch(e){errors.push(e.message);}}progress('封面 '+cover.options[i].label+'/C');}for(let i=0;i<t.quick.images.length;i++){if(stop)break;const s=t.quick.images[i];if(!C.assetOK(C.selected(s),'image')){try{await generateSlot(`${path}.quick.images.${i}`,'image');}catch(e){errors.push(e.message);}}progress('参考图 '+(i+1)+'/'+t.quick.images.length);}for(const[k,label]of C.PHASES){if(stop)break;const s=t.quick.videos[k];const a=C.selected(s);if(!C.assetOK(a,'video')||Math.abs(a.duration-8)>0.15||a.source!=='ai'){try{await generateSlot(`${path}.quick.videos.${k}`,'video',8);}catch(e){errors.push(e.message);}}progress(label+'视频已处理');}if(errors.length)throw Error(`${errors.length}项未完成：${errors[0]}`);}
async function projectText(p){
  const target=C.sessionTarget(p),existing=p.topicIds.map(id=>db.topics.find(t=>t.id===id)).filter(Boolean);
  if(existing.length!==p.topicIds.length||new Set(p.topicIds).size!==p.topicIds.length)throw Error('关联脚本无效，请先重新关联');
  const needed=target-existing.length;if(needed<0)throw Error('请先调整计划片数');
  const raw=await chat(`为一个共${target}条片的专场规划方向汇报。只补充缺少的${needed}条故事方向，不生成任何图片或视频，不覆盖已有脚本。根据项目写出的各类型数量严格分工；如需求总数与计划片数冲突，返回{"conflict":"说明冲突"}，不得擅自更改片数。每条包含故事概念、情绪走向、差异化任务、封面钩子和待确认项。已有故事需要保持不变。\n项目：${JSON.stringify({...p,referenceLibrary:referenceContext(p,'project')})}\n已有故事：${JSON.stringify(existing.map(t=>({title:t.title,idea:t.idea})))}\n只输出JSON：{"fields":${JSON.stringify(Object.fromEntries(C.SESSION.map(([k,l])=>[k,l])))},"stories":[恰好${needed}个对象，每个{"title":"名称","idea":"概念、走向、分工、封面钩子及待确认项"}]}`,folderImageIDs(p,'project'));
  if(C.text(raw.conflict))throw Error('需求需要核对：'+raw.conflict);
  const fields=C.validateFields(raw.fields,C.SESSION);
  if(!Array.isArray(raw.stories)||raw.stories.length!==needed||raw.stories.some(s=>!C.text(s.title)||!C.text(s.idea)))throw Error(`AI必须补充${needed}条有效故事方向，原项目已保留`);
  const titles=[...existing.map(t=>t.title.trim()),...raw.stories.map(t=>t.title.trim())];
  if(new Set(titles).size!==titles.length)throw Error('AI返回了重复故事名称，原项目已保留');
  for(const[k]of C.SESSION)if(!C.text(p.fields[k]))p.fields[k]=fields[k];
  raw.stories.forEach(s=>{const t=C.topic(s.title,p.id);t.idea=s.idea;db.topics.push(t);p.topicIds.push(t.id);});save();
}
async function deepFields(t){if(!t.quick.approved&&!t.directionApproved)throw Error('请先确认文字方向或完整汇报');const raw=await chat(`深化以下已确认创意。考虑真实场地约束、人物表演、预算排期和拍摄可行性。未知报价和尺寸列待确认。${JSON.stringify(context(t))}\n返回JSON：{"fields":${JSON.stringify(Object.fromEntries(C.DEEP.map(([k,l])=>[k,l])))}}`,referenceIDs(t));const fields=C.validateFields(raw.fields,C.DEEP);C.snapshot(t,'补全执行方案之前');for(const[k]of C.DEEP)if(!C.text(t.deep.fields[k]))t.deep.fields[k]=fields[k];save();}
async function deepShots(t){if(!C.text((t.quick.approved||t.directionApproved)?.fields?.script))throw Error('请先补全故事脚本并确认文字方向');const raw=await chat(`按确认的完整故事脚本拆分恰好25镜，严格延续人物、造型、空间和情绪，镜头有可剪辑的衔接。默认4:3，兼顾9:16/16:9。每镜2–12秒整数，时长总和应符合剧本。${JSON.stringify(context(t))}\n执行方案：${JSON.stringify(t.deep.fields)}\n返回JSON：{"shots":[25个对象，每个{"visual":"具体画面","dialogue":"台词与声音，无台词时写无台词","camera":"景别、运镜、焦段、灯光","duration":3,"imagePrompt":"参考图提示词","videoPrompt":"该镜动作、运镜与声音提示词"}]}`,referenceIDs(t));const shots=C.validateShots(raw);C.snapshot(t,'重新拆分25镜之前');t.deep.shots=shots;t.deep.film=null;save();}
async function assembleFilm(t){const s=C.deepStatus(t);if(t.deep.shots.length!==25||s.images!==25||s.videos!==25)throw Error('需先补齐25张AI分镜图和25段对应AI视频');const missing=C.DEEP.filter(([k])=>!C.text(t.deep.fields[k]));if(missing.length)throw Error('请先完成执行方案：'+missing.map(([,v])=>v).join('、'));const fingerprint=C.shotFingerprint(t.deep.shots);const bgmId=t.deep.bgm?.localId||null;const clips=t.deep.shots.map(s=>({localId:C.selected(s.video).localId,duration:s.duration,ratio:'4:3'}));const submission=await api('assemble',{clips,bgm:t.deep.bgm?.localId});const film=await pollJob(submission.jobId);if(t.deep.film)C.snapshot(t,'合成新版成片之前');t.deep.film={...film,fingerprint,bgmId};save();}
function previewHTML(t){const c=C.ensureCover(t);return `<div class="report-cover"><small>单条创意汇报</small><h1>${esc(t.title)}</h1></div>${readiness(C.quickStatus(t))}${C.QUICK.map(([k,label])=>`<div class="preview-block"><h2>${label}</h2><p class="preview-copy">${esc(t.quick.fields[k]||'待补充')}</p></div>`).join('')}<div class="preview-block"><h2>视频封面推荐</h2><p class="preview-copy">首选理由：${esc(c.recommendation||'待补充')}</p><div class="grid cover-grid">${c.options.map(o=>`<div><h3>${o.label} · ${esc(o.angle)}</h3>${coverMediaMarkup(C.selected(o.image),o,c.ratio,o.id===c.selectedId)}<p>${esc(o.description||'待补充')}</p></div>`).join('')}</div></div><div class="preview-block"><h2>视觉参考</h2><div class="grid">${t.quick.images.map(s=>mediaMarkup(C.selected(s))).join('')}</div></div><div class="preview-block"><h2>开场／中间／结尾各8秒</h2>${C.PHASES.map(([k,label])=>`<h3>${label}</h3>${mediaMarkup(C.selected(t.quick.videos[k]))}`).join('')}</div>`;}
function showSettings(){const labels={director:'内容总监 · Doubao-Seed-2.1-pro',refine:'日常提炼 · Doubao-Seed-2.1-turbo',image:'快速视觉 · Seedream-5.0-lite',video:'动态预演 · Seedance-2.0-fast',speech:'语音记录 · 豆包录音文件识别2.0',embedding:'审美检索 · Doubao-embedding-vision'};dialog('生成服务与模型连接',`<p class="muted">所有密钥和实际模型ID只在服务端配置。GitHub Pages不保存、接收或转发密钥。这里仅显示配置；有模型ID不等于账户已开通或真实调用已验证。</p><label>工作台服务地址（同源服务留空）<input id="cfg-server" value="${esc(settings.server)}"></label><div class="list">${Object.entries(labels).map(([k,l])=>`<div class="row"><span>${l}</span><small>${esc(health?.routes?.[k]?.model||'服务端待配置')}</small></div>`).join('')}</div><p class="muted">本机工具：FFmpeg ${health?.ffmpeg?'可用':'缺失'} · PDF文本 ${health?.pdfText?'可用':'缺失'} · 扫描PDF OCR ${health?.ocr?'可用':'缺失'}。</p><p id="connection-result" class="muted">连接检查不调用付费模型。不需要AK/SK或Supabase服务端密钥的功能不要配置额外权限。</p>`,btn('保存并检查连接','save-settings','',true));}
async function backup(){if(!window.JSZip)throw Error('备份组件未加载');const zip=new JSZip();const backupData=C.clone(db);await backupFragmentAudio(zip,backupData);zip.file('studio.json',JSON.stringify({scope,data:backupData,aesthetic:globalAssets(),folders:referenceFolders()},null,2));const ids=[...new Set(JSON.stringify([db,globalAssets()]).match(/[a-f0-9]{32}\.(?:mp4|mov|webm|jpg|jpeg|png|webp|pdf|mp3|wav|m4a|ogg|docx|txt|md)/g)||[])];for(const id of ids){const response=await fetch(mediaURL({localId:id}));if(!response.ok)throw Error('备份中断：素材'+id+'无法读取，未交付不完整备份');zip.file('media/'+id,await response.blob());progress('备份素材');}downloadBlob(await zip.generateAsync({type:'blob'}),'Lance完整备份_'+scope+'.zip');}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function restore(file){const zip=await JSZip.loadAsync(file);if(!zip.file('studio.json'))throw Error('不是Lance工作台备份');const raw=JSON.parse(await zip.file('studio.json').async('string'));if(raw.data?.version!==2||!Array.isArray(raw.data.topics)||!Array.isArray(raw.data.assets))throw Error('备份格式错误');let json=JSON.stringify(raw.data);let aesthetic=JSON.stringify(raw.aesthetic||[]);for(const name of Object.keys(zip.files).filter(n=>n.startsWith('media/')&&!zip.files[n].dir)){const bytes=await zip.files[name].async('blob');const result=await api('upload',new File([bytes],name.split('/').at(-1)));const old=name.split('/').at(-1);json=json.split(old).join(result.localId);aesthetic=aesthetic.split(old).join(result.localId);progress('恢复素材');}const restored=JSON.parse(json);const restoredShared=JSON.parse(aesthetic);const restoredFolders=StudioFolders.restore(raw.folders||[],restored,restoredShared,C.uid);aesthetic=JSON.stringify(restoredShared);await restoreFragmentAudio(zip,restored);if(restored.profile)db.profileImports.push(restored.profile);for(const i of restored.inspirations||[])db.inspirations.push({...i,id:C.uid()});const suffix='（恢复副本）';const projectMap=new Map(restored.projects.map(p=>[p.id,C.uid()]));const topicMap=new Map(restored.topics.map(t=>[t.id,C.uid()]));restored.projects.forEach(p=>{p.id=projectMap.get(p.id);p.title+=suffix;p.topicIds=p.topicIds.map(id=>topicMap.get(id)).filter(Boolean);});restored.topics.forEach(t=>{C.ensureCover(t);t.id=topicMap.get(t.id);t.title+=suffix;t.projectId=projectMap.get(t.projectId)||null;});restored.assets.forEach(a=>{a.id=C.uid();a.name+=suffix;a.projectId=projectMap.get(a.projectId)||null;});const reverseMap=new Map((restored.reverse||[]).map(r=>[r.id,C.uid()]));for(const r of restored.reverse||[]){r.id=reverseMap.get(r.id);r.title+=suffix;r.projectId=projectMap.get(r.projectId)||null;r.topicIds=(r.topicIds||[]).map(id=>topicMap.get(id)).filter(Boolean);}for(const t of restored.topics)if(t.sourceReverse)t.sourceReverse.id=reverseMap.get(t.sourceReverse.id)||t.sourceReverse.id;db.reverse.push(...(restored.reverse||[]));db.projects.push(...restored.projects);db.topics.push(...restored.topics);db.assets.push(...restored.assets);const globals=globalAssets();JSON.parse(aesthetic).forEach(a=>{a.id=C.uid();a.name+=suffix;a.usedIn=(a.usedIn||[]).filter(p=>p.scope===raw.scope&&projectMap.has(p.id)).map(p=>({scope,id:projectMap.get(p.id)}));globals.push(a);});saveAesthetic(globals);if(restoredFolders.length)saveReferenceFolders([...referenceFolders(),...restoredFolders]);save();}
async function extractAssetFrames(a,fileIndex){const file=a.files[fileIndex];const submission=await api('frames',{localId:file.localId});const frames=await pollJob(submission.jobId);a.frames.push(...frames);save();}
async function analyzeAsset(a){const files=a.kind==='wardrobe'?a.frames:a.files.filter(f=>f.kind==='image');if(!files.length)throw Error(a.kind==='wardrobe'?'请先提取视频关键帧，或上传服装截图':'请上传清晰的尺寸图或场地照片');const refs=files.slice(-12);const prompt=a.kind==='scene'?`你是场景美术与摄影指导。读取尺寸图及参考，不编造无法辨认的尺寸。已核对尺寸：${a.dimensionsConfirmed}。尺寸：${a.dimensions}。目标：${a.requirements}。提出符合空间的布景、人物动线、机位、灯位、材料、预算估算依据与待核实限制。必须明确效果图不是施工图。返回{"analysis":"完整可编辑分析","prompt":"基于参考图的场景效果生成描述"}`:`分析这${refs.length}个视频关键帧的服装，合并重复造型。只识别可见衣服，不猜品牌、身份与看不清的材质。目标：${a.requirements}；库存条件：${a.inventory}。返回{"analysis":"整体造型与本项目推荐理由","prompt":"结合所选风格的搭配效果图描述","outfits":[{"frameIndex":0,"name":"造型名称","description":"上装/下装/配饰/色彩/廓形","recommendation":"适合的场景、人物、灯光与动作，哪些需确认"}]}`;
  const raw=await chat(prompt,refs.map(f=>f.localId));if(!C.text(raw.analysis)||!C.text(raw.prompt))throw Error('分析结果不完整，原稿已保留');a.analysis=raw.analysis;if(!a.proposal.locked)a.proposal.prompt=raw.prompt;if(a.kind==='wardrobe'){if(!Array.isArray(raw.outfits))throw Error('未识别到造型列表');a.outfits=raw.outfits.filter(o=>Number.isInteger(o.frameIndex)&&o.frameIndex>=0&&o.frameIndex<refs.length).map(o=>({...o,frameIndex:a.frames.indexOf(refs[o.frameIndex]),selected:false}));}save();}
document.addEventListener('change',async event=>{
  const e=event.target;
  try{
    if(e.id==='scope'){if(job||fragmentRecording||fragmentPending){e.value=scope;throw Error('生成期间请先停止后续任务，再切换空间');}fragmentSelected.clear();fragmentSearch='';referenceFolder='all';aestheticQuery={category:'全部',tag:'全部',search:'',favorite:false,page:1};scope=e.value;localStorage.setItem('lance_studio_scope',scope);db=read(scope);route={view:'home'};save();render();applyProfileSeed();return;}
    if(e.hasAttribute('data-session-count')){if(job)throw Error('请先结束当前任务');const p=db.projects.find(p=>p.id===e.dataset.sessionCount);C.setSessionTarget(p,e.value);save();render();return;}
    if(e.hasAttribute('data-budget')){if(job)throw Error('请先结束当前任务');set(e.dataset.field,Number(e.value));db.budgetPlan=C.budgetPlan(db.budgetPlan);save();render();return;}
    if(e.dataset.field){if(job)throw Error('生成过程中暂不修改，停止后可打磨');set(e.dataset.field,e.hasAttribute('data-bool')?e.checked:e.hasAttribute('data-number')?Number(e.value):e.value);save();refreshReadiness();return;}
    if(e.dataset.version){const s=get(e.dataset.version);if(s.locked)throw Error('参考已锁定');s.selectedId=e.value;s.prompt=C.selected(s)?.prompt||s.prompt;save();render();return;}
    if(e.dataset.topicProject){const t=db.topics.find(t=>t.id===e.dataset.topicProject);const p=db.projects.find(p=>p.id===e.value);if(p&&!p.topicIds.includes(t.id)&&p.topicIds.length>=C.sessionTarget(p)&&!isPersonalProject(p))throw Error('已达到计划片数，请先增加专场计划片数或调整关联');db.projects.forEach(p=>p.topicIds=p.topicIds.filter(id=>id!==t.id));t.projectId=e.value||null;if(p)p.topicIds.push(t.id);save();render();return;}
    if(e.dataset.upload==='fragment-audio'){if(job||fragmentRecording||fragmentPending)throw Error('请先保存当前录音或结束任务');await fragmentAudioFile(e);return;}
    if(e.dataset.upload?.startsWith('aesthetic-')){await aestheticFiles(e);return;}
    if(e.dataset.upload==='profile-files'){await profileFiles(e);return;}
    if(e.dataset.upload==='reverse-support'){await reverseSupportFiles(e);return;}
    if(e.dataset.upload){if(!e.files[0])return;const file=e.files[0];if(job)throw Error('请等当前处理完成');await withJob('上传与核验',1,async()=>{
      if(e.dataset.upload==='restore'){await restore(file);return;}
      await ensureService();const result=await api('upload',file);result.name=file.name;
      if(e.dataset.upload==='reverse-video'){if(result.kind!=='video')throw Error('请上传视频');const r=db.reverse.find(x=>x.id===e.dataset.id);r.video=result;r.frames=[];r.analysis=null;r.transcript='';r.transcriptions=[];r.error='';}
      if(e.dataset.upload==='slot'){const kind=e.dataset.kind;if((kind==='video'||e.dataset.path.includes('.deep.'))&&!confirm('请确认：这份上传素材是AI生成的参考。系统会核验文件和时长，但无法鉴定它是否由AI制作。'))return;if(result.kind!==kind)throw Error('素材类型不匹配');if(kind==='video'){const duration=Number(e.dataset.duration);if(Math.abs(result.duration-duration)>0.15)throw Error(`实际${result.duration.toFixed(2)}秒，需要${duration}秒`);result.source='ai';result.provenance='用户声明为AI视频参考';}if(e.dataset.path.includes('.deep.')&&kind==='image'){result.source='ai';result.provenance='用户声明为AI分镜参考';}C.putVersion(get(e.dataset.path),result);}
      if(e.dataset.upload==='asset'){const a=db.assets.find(a=>a.id===e.dataset.id);a.files.push(result);if(a.kind==='wardrobe'&&result.kind==='image')a.frames.push(result);}
      if(e.dataset.upload==='bgm'){if(result.kind!=='audio')throw Error('请上传音频文件');db.topics.find(t=>t.id===e.dataset.id).deep.bgm=result;}
      if(e.dataset.upload==='global'){const all=globalAssets();const a=all.find(a=>a.id===e.dataset.id);a.files.push(result);saveAesthetic(all);}
      save();progress('素材已核验并保存');
    });}
  }catch(error){showError(error);if(!$('#dialog')?.open)render();}
});
let fieldSaveTimer=null;
document.addEventListener('input',event=>{const e=event.target;if(e.dataset.field&&!job){set(e.dataset.field,e.hasAttribute('data-number')?Number(e.value):e.value);clearTimeout(fieldSaveTimer);fieldSaveTimer=setTimeout(()=>{save();refreshReadiness();},220);}if(e.id==='search'){search=e.value;const pos=e.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);}});
document.addEventListener('input',event=>{if(event.target.hasAttribute('data-reverse-search')){route.query=event.target.value;const pos=event.target.selectionStart;render();$('[data-reverse-search]')?.focus();$('[data-reverse-search]')?.setSelectionRange(pos,pos);}});
document.addEventListener('click',async event=>{
  const e=event.target.closest('[data-action]');if(!e)return;const action=e.dataset.action;const t=db.topics.find(t=>t.id===e.dataset.id);const p=db.projects.find(p=>p.id===e.dataset.id);const a=db.assets.find(a=>a.id===e.dataset.id);
  try{
    if(fragmentRecording&&action!=='fragment-stop')throw Error('请先停止并保存录音');
    if(fragmentPending&&!['fragment-retry','fragment-download-pending'].includes(action))throw Error('请先重试保存录音，或下载保底；不要离开页面');
    if(job&&!['stop','close','nav','topic','deep','project','asset'].includes(action))throw Error('当前任务仍在运行，请先等待或停止后续生成');
    if(action.startsWith('fragment-')){await fragmentAction(action,e);return;}
    if(action.startsWith('reverse-')){await reverseAction(action,e);return;}
    if(action.startsWith('folder-')){await folderAction(action,e);return;}
    if(action.startsWith('aesthetic-')){await aestheticAction(action,e);return;}
    if(action.startsWith('radar-')){await radarAction(action,e);return;}
    if(action.startsWith('profile-')){await profileAction(action,e);return;}
    if(action.startsWith('supply-')){await supplyAction(action,e);return;}
    if(action.startsWith('mobile-')){await mobileInboxAction(action,e);return;}
    if(action==='stop'){stop=true;render();return;}
    if(action==='close'){close();return;}
    if(action==='reveal-material'){revealResult(e.dataset.target);return;}
    if(action==='nav'){route={view:e.dataset.view};search='';render();if(route.view==='fragments'){window.scrollTo({top:0,behavior:'instant'});$('#fragment-capture-heading')?.focus({preventScroll:true});}return;}
    if(['topic','deep','project','asset'].includes(action)){route={view:action==='deep'?'topic':action,id:e.dataset.id,tab:action==='deep'?'deep':scope==='personal'?'idea':'quick'};render();return;}
    if(action==='new-topic'||action==='new-project'){dialog(action==='new-topic'?'建立单条脚本':scope==='personal'?'建立个人项目':'建立整体专场',`<label>名称<input id="new-title" required placeholder="例如：下播后的最后一束光"></label><label style="margin-top:14px">创意想法<textarea id="new-idea" placeholder="想说什么、拍谁、给谁看、希望观众感受到什么"></textarea></label>${action==='new-project'&&scope!=='personal'?'<label>计划片数（之后可调整）<input id="new-count" type="number" min="1" max="100" value="6"></label>':''}`,btn('创建并开始','create',`data-kind="${action==='new-topic'?'topic':'project'}"`,true));return;}
    if(action==='create'){const title=$('#new-title').value.trim();if(!title)throw Error('请填写名称');const item=e.dataset.kind==='topic'?C.topic(title):C.project(title);if(e.dataset.kind==='project'&&scope!=='personal')C.setSessionTarget(item,$('#new-count').value);if(e.dataset.kind==='project'&&scope==='personal'){item.kind='personal';item.projectType='其他';item.personalRole='导演、摄影师、个人博主';}item.idea=$('#new-idea').value;db[e.dataset.kind==='topic'?'topics':'projects'].push(item);route={view:e.dataset.kind,id:item.id,tab:scope==='personal'?'idea':'quick'};save();close();render();return;}
    if(action==='workflow-stage'){if(p)p.stage=e.dataset.stage;else{t.quick.stage=e.dataset.stage;route.tab='quick';}save();render();return;}
    if(action==='workflow-go'){const step=Number(e.dataset.step);if(step===1){t.quick.stage='direction';route.tab='direction';}else if(step===2){if(!t.directionApproved)throw Error('请先确认文字方向');t.quick.stage='full';route.tab='quick';}else if(step===3){if(!t.quick.approved)throw Error('请先确认完整快速汇报');route.tab='deep';}else if(step===4){if(!C.deepStatus(t).ready)throw Error('请先完成深入优化和AI成片');showReportOptions(t,'topic','execution');return;}save();render();return;}
    if(action==='topic-settings'){const path=`topics.${ts(t)}`;dialog('项目设定',`<label>脚本名称<input data-field="${path}.title" value="${esc(t.title)}"></label><label>原始想法与本轮修改要求<textarea data-field="${path}.idea">${esc(t.idea)}</textarea></label><label>所属项目<select data-topic-project="${t.id}"><option value="">独立脚本</option>${db.projects.map(project=>`<option value="${project.id}" ${project.id===t.projectId?'selected':''}>${esc(project.title)}</option>`).join('')}</select></label>`,btn('完成','close','',true));return;}
    if(action==='settings'){showSettings();return;}
    if(action==='save-settings'){const server=$('#cfg-server').value.trim().replace(/\/$/,'');if(server&&!/^https?:\/\//.test(server))throw Error('服务地址需要以http://或https://开头');settings={server};localStorage.setItem('lance_studio_settings',JSON.stringify(settings));try{health=await api('health');$('#connection-result').textContent=`服务已连接；${health.ffmpeg?'媒体核验可用':'缺少FFmpeg'}；${health.keyConfigured?'服务端已配置Key，真实调用尚待验证':'服务端尚未配置API Key'}`;}catch(err){$('#connection-result').textContent=err.message;}return;}
    if(action==='add-image'){if(t.quick.images.length>=5)return;t.quick.images.push(C.slot('补充视觉'+(t.quick.images.length+1)));save();render();return;}
    if(action==='remove-image'){if(t.quick.images.length<=3)return;C.snapshot(t,'调整参考图数量前');t.quick.images.pop();save();render();return;}
    if(action==='lock'){const s=get(e.dataset.path);if(!s.locked&&!C.selected(s))throw Error('先生成或上传参考，才能锁定');s.locked=!s.locked;save();render();return;}
    if(action==='generate-slot'){const section=resultSectionForPath(e.dataset.path),hadAsset=!!C.selected(get(e.dataset.path));const ok=await withJob('生成单项参考',1,async()=>{await ensureService();await generateSlot(e.dataset.path,e.dataset.kind,Number(e.dataset.duration));progress('本项已回填');},hadAsset?'新版本已替换当前画面；旧版仍在历史版本中。':'素材已自动回填到当前卡位。');if(ok)revealResult(section);return;}
    if(action==='quick-text'){await withJob('补全创意与脚本',1,async()=>{await generateQuickText(t);progress('文本已补全');});return;}
    if(action==='quick-all'){const estimate=C.quickGenerationCost(t);if(!confirm(`本次将补齐${estimate.images}张图片和${estimate.videoSeconds}秒AI视频，保守估算约¥${estimate.cost.toFixed(0)}（实际账单为准）。方向汇报不需要此步骤。确定开始？`))return;const ok=await withJob('快速汇报素材生成',1+3+t.quick.images.length+3,async()=>{await ensureService();await quickAll(t);},'快速汇报已生成：图片和视频已自动回填到本脚本对应位置。');if(ok)revealResult('quick-images');return;}
    if(action==='project-text'){await withJob(`专场方向规划 · ${C.sessionTarget(p)}条片`,1,async()=>{await projectText(p);progress('已保存整体方案和脚本规划');});return;}
    if(action==='project-all'){if(!C.directionStatus(p,'project',db.topics).ready)throw Error('先完成方向与计划片数的故事分工');const estimate=p.topicIds.map(id=>db.topics.find(t=>t.id===id)).filter(Boolean).map(C.quickGenerationCost).reduce((a,x)=>({images:a.images+x.images,videoSeconds:a.videoSeconds+x.videoSeconds,cost:a.cost+x.cost}),{images:0,videoSeconds:0,cost:0});if(!confirm(`即将为${C.sessionTarget(p)}条片补齐${estimate.images}张图片和${estimate.videoSeconds}秒AI视频，保守估算约¥${estimate.cost.toFixed(0)}（实际账单为准）。方向PPT不需要此步骤。确定开始？`))return;await withJob(`专场完整交付 · ${C.sessionTarget(p)}条故事`,p.topicIds.reduce((n,id)=>n+7+db.topics.find(t=>t.id===id).quick.images.length,0),async()=>{await ensureService();const errors=[];for(const id of p.topicIds){if(stop)break;try{await quickAll(db.topics.find(t=>t.id===id));}catch(err){errors.push(err.message);}}if(errors.length)throw Error('部分脚本素材未齐备：'+errors.join('；'));});return;}
    if(action==='deep-fields'||action==='deep-shots'){await withJob(action==='deep-fields'?'完善执行方案':'拆解25镜',1,async()=>{await (action==='deep-fields'?deepFields(t):deepShots(t));progress('结果已保存');});return;}
    if(action==='deep-images'||action==='deep-videos'){if(!(t.quick.approved||t.directionApproved)||t.deep.shots.length!==25)throw Error('请先确认方向并拆解25镜');const kind=action==='deep-images'?'image':'video',estimate=C.deepGenerationCost(t,kind);if(!confirm(`本次将补齐${estimate.images?estimate.images+'张AI分镜图':estimate.videoSeconds+'秒AI镜头'}，保守估算约¥${estimate.cost.toFixed(0)}（实际账单为准）。确定开始？`))return;await withJob(action==='deep-images'?'25张AI分镜参考':'25镜AI视频',25,async()=>{await ensureService();const errors=[];for(let j=0;j<25;j++){if(stop)break;const s=t.deep.shots[j],ref=C.selected(s[kind]);if(!C.assetOK(ref,kind)||ref.source!=='ai'||kind==='video'&&Math.abs(ref.duration-s.duration)>0.15){try{await generateSlot(`topics.${ts(t)}.deep.shots.${j}.${kind}`,kind,s.duration);}catch(err){errors.push(`镜${j+1}：${err.message}`);}}progress('镜'+(j+1)+'已处理');}if(errors.length)throw Error(errors.join('；'));});return;}
    if(action==='assemble'){await withJob('合成完整AI成片',1,async()=>{await ensureService();await assembleFilm(t);progress('成片已保存');});return;}
    if(action==='approve-direction'){if(!C.directionStatus(t).ready)throw Error('先填写创意方向与推荐理由');C.snapshot(t,'文字方向确认');t.directionApproved={time:new Date().toISOString(),fields:C.clone(t.quick.fields),report:C.clone(StudioPpt.ensureReport(t))};t.quick.stage='full';route.tab='quick';save();render();notify('文字方向已锁定，现在进入完整素材阶段。');return;}
    if(action==='approve'){if(!C.quickStatus(t).ready)throw Error('快速汇报缺项，暂不能确认');C.snapshot(t,'汇报确认版');t.quick.approved={time:new Date().toISOString(),report:C.clone(StudioPpt.ensureReport(t)),fields:C.clone(t.quick.fields),cover:C.clone(C.ensureCover(t)),images:t.quick.images.map(s=>({...C.selected(s),referenceNote:s.referenceNote||''})),videos:C.clone(t.quick.videos),feedback:C.clone(t.feedback)};route.tab='deep';save();render();return;}
    if(action==='feedback'){dialog('记录汇报反馈',`<label>采纳的方向、需要修改的地方<textarea id="feedback-text"></textarea></label>`,btn('保存反馈和当前快照','save-feedback',`data-id="${t.id}"`,true));return;}
    if(action==='save-feedback'){const text=$('#feedback-text').value.trim();if(!text)throw Error('请填写反馈');t.feedback.push({time:new Date().toISOString(),text});C.snapshot(t,text);save();close();render();return;}
    if(action==='snapshot'){const snap=t.snapshots.find(s=>s.id===e.dataset.snapshot);dialog(snap.note,previewHTML(snap.data));return;}
    if(action==='preview-topic'){dialog(t.title,route.tab==='deep'?deepPreviewHTML(t):previewHTML(t));return;}
    if(action==='preview-project'){dialog(p.title,readiness(C.sessionStatus(p,db.topics))+C.SESSION.map(([k,l])=>`<div class="preview-block"><h2>${l}</h2><p class="preview-copy">${esc(p.fields[k]||'待补充')}</p></div>`).join('')+p.topicIds.map(id=>db.topics.find(t=>t.id===id)).filter(Boolean).map(previewHTML).join(''));return;}
    if(action==='export-topic'||action==='export-project'){showReportOptions(t||p,t?'topic':'project',t&&route.tab==='deep'?'execution':(p?p.stage:t.quick.stage)==='full'?'full':'decision');return;}
    if(action==='report-options'){showReportOptions(t||p,e.dataset.kind,e.dataset.mode);return;}
    if(action==='report-refine'){const item=t||p;await withJob('提炼汇报要点',1,async()=>{const fields=StudioPpt.REPORT_FIELDS.filter(([k])=>k!=='confirmed');const raw=await chat('根据已有策划提炼供内容总监汇报的要点。保留明确的不确定性，未知日期、预算、人员、尺寸写待确认。不要把需求、假设或AI建议宣称为已确认事实。不增加人物经历与业务承诺。每个字段尽量120字以内，主推方向50字以内。仅输出JSON，结构：'+JSON.stringify(Object.fromEntries(fields.map(([k,label])=>[k,label])))+'\n现有策划：'+JSON.stringify({title:item.title,idea:item.idea,fields:t?t.quick.fields:p.fields,report:StudioPpt.ensureReport(item),stories:p?p.topicIds.map(id=>db.topics.find(t=>t.id===id)).filter(Boolean).map(t=>({title:t.title,idea:t.idea})):undefined}));for(const[k,label]of fields)if(typeof raw[k]!=='string'||k!=='alternatives'&&!C.text(raw[k]))throw Error('AI未提供'+label+'，原内容已保留');const report=StudioPpt.ensureReport(item);for(const[k]of fields)if(!C.text(report[k]))report[k]=raw[k];save();progress('汇报要点已补全，请核对建议；已确认事实由你填写');});return;}
    if(action==='report-download'){close();await withJob('生成'+StudioPpt.MODES[e.dataset.mode],1,async()=>{await StudioPpt.exportReport(t||p,e.dataset.kind,{db,mediaURL,api,downloadBlob,progress,save},e.dataset.mode);});return;}
    if(action==='redownload'){const record=db.exports.find(x=>x.id===e.dataset.id);const blob=await StudioPpt.getExport(record.id);if(!blob)throw Error('本机成果文件不存在，可从对应脚本重新导出');downloadBlob(blob,StudioPpt.filename(record));return;}
    if(action==='link-topics'){dialog(isPersonalProject(p)?'选择个人项目脚本':`选择本专场脚本（计划${C.sessionTarget(p)}条）`,`<p class="muted">已关联其他专场的脚本不在此处移动。可在单条脚本里调整所属项目。</p>${db.topics.filter(t=>!t.projectId||t.projectId===p.id).map(t=>`<label class="file-row"><input type="checkbox" name="topic-link" value="${t.id}" ${p.topicIds.includes(t.id)?'checked':''}> ${esc(t.title)}</label>`).join('')}`,btn('保存关联','save-links',`data-id="${p.id}"`,true));return;}
    if(action==='save-links'){const ids=[...document.querySelectorAll('[name=topic-link]:checked')].map(n=>n.value);if(ids.length>C.sessionTarget(p)&&!isPersonalProject(p))throw Error('超出计划片数，请先调整专场计划片数');db.topics.filter(t=>t.projectId===p.id).forEach(t=>t.projectId=null);ids.forEach(id=>db.topics.find(t=>t.id===id).projectId=p.id);p.topicIds=ids;save();close();render();return;}
    if(action==='new-asset'){dialog('建立参考专题',`<div class="formgrid"><label>专题名称<input id="asset-name"></label><label>分类／标签<input id="asset-category" placeholder="例如：黑色造型／主舞台"></label><label>类型<select id="asset-kind">${[['scene','场景'],['wardrobe','服装'],['aesthetic','其他审美']].map(([k,l])=>`<option value="${k}" ${e.dataset.kind===k?'selected':''}>${l}</option>`).join('')}</select></label><label>所属项目<select id="asset-project"><option value="">不关联</option>${db.projects.map(p=>`<option value="${p.id}" ${p.id===e.dataset.project?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label></div>`,btn('建立专题','create-asset','',true));return;}
    if(action==='create-asset'){const name=$('#asset-name').value.trim();if(!name)throw Error('请填写专题名称');const asset={id:C.uid(),folderIds:referenceFolders().some(f=>f.id===referenceFolder)?[referenceFolder]:[],name,category:$('#asset-category').value,kind:$('#asset-kind').value,projectId:$('#asset-project').value||null,requirements:'',dimensions:'',dimensionsConfirmed:false,inventory:'',analysis:'',files:[],frames:[],outfits:[],proposal:C.slot('AI效果参考')};if(asset.kind==='aesthetic'){const all=globalAssets();all.push(asset);saveAesthetic(all);route={view:'aesthetic'};}else{db.assets.push(asset);route={view:'asset',id:asset.id};save();}close();render();return;}
    if(action==='global-asset'){aestheticDialog(globalAssets().find(a=>a.id===e.dataset.id));return;}
    if(action==='frames'){await withJob('提取候选关键帧',1,async()=>{await extractAssetFrames(a,Number(e.dataset.file));progress('关键帧已保存');});return;}
    if(action==='analyze-asset'){await withJob('分析项目资料',1,async()=>{await analyzeAsset(a);progress('分析已保存，等待你核对');});return;}
    if(action==='backup'){await withJob('完整备份',1,backup);return;}
  }catch(error){showError(error);}
});
window.addEventListener('beforeunload',event=>{if(job||fragmentRecording||fragmentPending){event.preventDefault();event.returnValue='';}});
try{db=read(scope);save();render();applyProfileSeed();api('health',undefined,{timeout:5000}).then(h=>{health=h;render();}).catch(()=>{});}catch(error){$('#app').textContent=error.message;}
